-- Lessons generated by supabase/lessons/build.mjs — edit the .mjs sources, not this file.

-- Lesson 2: Чьё это? Вещи и принадлежность (7 sections, 90 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('whose', 'Чьё это? Вещи и принадлежность', 'вещи, this / these / that / those, my / mine, whose, ''s', 2, $lesson${"sections":[{"id":"things","nav":"Вещи","eyebrow":"Тема 1 · лексика","title":"Вещи, которые мы носим с собой","theory":"<p>Слова из урока «After the party» и с ваших стикеров: что обычно лежит в сумке, в кармане и дома.</p>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>В сумке и в кармане</h4><ul><li>wallet — кошелёк (для денег и карт)</li><li>purse — кошелёчек, женский кошелёк</li><li>keys — ключи</li><li>phone charger — зарядка для телефона</li><li>driving licence — водительские права</li><li>notebook — блокнот, тетрадь</li><li>laptop — ноутбук</li><li>hairbrush — расчёска</li><li>make-up — косметика</li></ul></div><div class=\"ng\"><h4>Одежда и украшения</h4><ul><li>cap — кепка</li><li>scarf — шарф</li><li>gloves — перчатки</li><li>sweater — свитер</li><li>handbag — дамская сумка</li><li>necklace — ожерелье, цепочка</li><li>earrings — серьги</li><li>sunglasses — солнцезащитные очки</li><li>a present / a gift — подарок</li></ul></div></div>\n<h3>Одна вещь или пара</h3>\n<p>Некоторые вещи по-английски всегда во множественном числе, потому что состоят из двух частей: <b>gloves, earrings, sunglasses, glasses, keys</b>. С ними — <b>are, these, those, they</b>.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Это мои перчатки.</span><span class=\"en\">These <mark>are</mark> my gloves.</span><span class=\"why\">gloves — несколько → are</span></li>\n<li><span class=\"ru\">Где мои очки?</span><span class=\"en\">Where <mark>are</mark> my sunglasses?</span><span class=\"why\">sunglasses → они → are</span></li>\n<li><span class=\"ru\">Этот шарф новый.</span><span class=\"en\">This scarf <mark>is</mark> new.</span><span class=\"why\">scarf — одна вещь → is</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Пишется hairb<b>r</b>u<b>sh</b>: <span class=\"no\">hairbrash</span> <span class=\"yes\">hairbrush ✔</span></span><span>licence — британское написание, license — американское. Оба варианта правильные, в учебнике — <span class=\"yes\">driving licence ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>wallet · bag · keys · driving license · (sun)glasses · phone · gift / present · laptop</span></div>","groups":[{"title":"Выберите слово","items":[{"t":"choice","q":"«кошелёк» — ___","o":["wallet","necklace","notebook"],"a":"wallet","ex":"wallet — кошелёк. necklace — ожерелье, notebook — блокнот."},{"t":"choice","q":"«перчатки» — ___","o":["gloves","scarf","sweater"],"a":"gloves","ex":"gloves — перчатки. Всегда во множественном числе."},{"t":"choice","q":"«зарядка для телефона» — ___","o":["phone charger","phone cap","phone licence"],"a":"phone charger","ex":"charge — заряжать, charger — зарядка."},{"t":"choice","q":"«водительские права» — ___","o":["driving licence","driver paper","car licence"],"a":"driving licence","ex":"driving licence (брит.) = driver's license (амер.)."},{"t":"choice","q":"«серьги» — ___","o":["earrings","rings","necklace"],"a":"earrings","ex":"ear — ухо + rings — кольца = earrings."},{"t":"choice","q":"«расчёска» — ___","o":["hairbrush","hairbrash","make-up"],"a":"hairbrush","ex":"hair — волосы, brush — щётка."}]},{"title":"Соберите слово из букв (как в домашнем задании)","items":[{"t":"input","q":"supre →","a":["purse"],"ex":"supre → purse.","p":"Переставьте буквы","h":"Пять букв, начинается на p."},{"t":"input","q":"fracs →","a":["scarf"],"ex":"fracs → scarf.","p":"Переставьте буквы","h":"Начинается на s."},{"t":"input","q":"wearset →","a":["sweater"],"ex":"wearset → sweater.","p":"Переставьте буквы","h":"Одежда, начинается на sw."},{"t":"input","q":"slogev →","a":["gloves"],"ex":"slogev → gloves.","p":"Переставьте буквы","h":"Начинается на g."},{"t":"input","q":"ringsear →","a":["earrings"],"ex":"ringsear → earrings.","p":"Переставьте буквы","h":"ear + rings."},{"t":"input","q":"klecenca →","a":["necklace"],"ex":"klecenca → necklace.","p":"Переставьте буквы","h":"neck — шея."}]},{"title":"is или are?","items":[{"t":"choice","q":"These gloves ___ very warm.","o":["is","are"],"a":"are","ex":"gloves — несколько → are."},{"t":"choice","q":"My sunglasses ___ in the car.","o":["is","are"],"a":"are","ex":"sunglasses всегда во множественном числе → are."},{"t":"choice","q":"This necklace ___ a present from my mum.","o":["is","are"],"a":"is","ex":"necklace — одна вещь → is."},{"t":"choice","q":"Your keys ___ on the table.","o":["is","are"],"a":"are","ex":"keys — несколько → are."}]}]},{"id":"this","nav":"this · these","eyebrow":"Тема 2 · указательные слова","title":"this, these, that, those","theory":"<p>Выбор зависит от двух вещей: <b>близко или далеко</b> и <b>один предмет или несколько</b>.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th></th><th>Один предмет</th><th>Несколько предметов</th></tr></thead>\n<tbody>\n<tr><td><b>Близко</b> (здесь, в руке)</td><td><mark>this</mark> — это, этот</td><td><mark>these</mark> — эти</td></tr>\n<tr><td><b>Далеко</b> (там)</td><td><mark>that</mark> — то, тот</td><td><mark>those</mark> — те</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Это мой телефон (у меня в руке).</span><span class=\"en\"><mark>This</mark> is my phone.</span></li>\n<li><span class=\"ru\">Эти ключи твои?</span><span class=\"en\">Are <mark>these</mark> your keys?</span><span class=\"why\">these + are</span></li>\n<li><span class=\"ru\">Та сумка очень красивая.</span><span class=\"en\"><mark>That</mark> bag is very nice.</span><span class=\"why\">далеко, одна</span></li>\n<li><span class=\"ru\">Те перчатки не мои.</span><span class=\"en\"><mark>Those</mark> gloves aren't mine.</span><span class=\"why\">далеко, несколько</span></li>\n</ul>\n<p>После <b>this / that</b> — <b>is</b>. После <b>these / those</b> — <b>are</b>.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Во множественном числе меняется и слово, и глагол: <span class=\"no\">This are my keys.</span> <span class=\"yes\">These are my keys. ✔</span></span><span>По-русски «это мои ключи», но по-английски не this: <span class=\"no\">This is my keys.</span> <span class=\"yes\">These are my keys. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>this – these · that – those (это – эти / тот – те)</span></div>","groups":[{"title":"Выберите слово","items":[{"t":"choice","q":"___ is my new laptop. (у вас в руках)","o":["This","These","Those"],"a":"This","ex":"Близко и один предмет → this."},{"t":"choice","q":"___ are my earrings. (у вас в руке)","o":["This","These","That"],"a":"These","ex":"Близко и несколько → these.","b":{"This":"earrings — несколько, поэтому these.","That":"That — для одного и далеко."}},{"t":"choice","q":"Look at ___ man over there!","o":["this","that","those"],"a":"that","ex":"over there — далеко, один человек → that."},{"t":"choice","q":"Whose are ___ bags over there?","o":["that","these","those"],"a":"those","ex":"Далеко и несколько → those."},{"t":"choice","q":"Is ___ your scarf? (показываете на шарф рядом)","o":["this","these","those"],"a":"this","ex":"Близко и один → this."},{"t":"choice","q":"___ gloves are too small for me. (они у вас на руках)","o":["This","These","Those"],"a":"These","ex":"Близко и несколько → these."}]},{"title":"Поставьте во множественное число","items":[{"t":"input","q":"This is my key.","a":["These are my keys."],"ex":"this → these, is → are, key → keys.","p":"Напишите про несколько предметов"},{"t":"input","q":"That is her bag.","a":["Those are her bags."],"ex":"that → those, is → are, bag → bags.","p":"Напишите про несколько предметов"},{"t":"input","q":"Is this your notebook?","a":["Are these your notebooks?"],"ex":"Is this → Are these, notebook → notebooks.","p":"Напишите про несколько предметов"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"This are my sunglasses.","w":0,"c":"These","ex":"sunglasses — несколько → These are."},{"t":"fix","q":"Those bag is very expensive.","w":0,"c":"That","ex":"bag — один предмет → That bag is."},{"t":"fix","q":"These shoes is new.","w":2,"c":"are","ex":"These shoes → are."}]}]},{"id":"my","nav":"my · your","eyebrow":"Тема 3 · притяжательные слова","title":"my, your, his, her… — перед предметом","theory":"<p>Слова «мой, твой, его…» ставятся <b>перед</b> существительным. Они не меняются по родам и числам: my bag, my keys, my sister.</p>\n<div class=\"formula\"><span class=\"slot be\">my · your · his · her · its · our · their</span><span class=\"plus\">+</span><span class=\"slot\">предмет</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Чей</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I</td><td><mark>my</mark> — мой</td><td>my phone</td></tr>\n<tr><td>you</td><td><mark>your</mark> — твой, ваш</td><td>your keys</td></tr>\n<tr><td>he</td><td><mark>his</mark> — его (о мужчине)</td><td>his wallet</td></tr>\n<tr><td>she</td><td><mark>her</mark> — её</td><td>her handbag</td></tr>\n<tr><td>it</td><td><mark>its</mark> — его / её (о предмете, животном)</td><td>its name</td></tr>\n<tr><td>we</td><td><mark>our</mark> — наш</td><td>our flat</td></tr>\n<tr><td>they</td><td><mark>their</mark> — их</td><td>their car</td></tr>\n</tbody></table></div>\n<h3>his или her</h3>\n<p>По-русски «его / её» зависит от предмета, а по-английски — от <b>владельца</b>. Сумка Тома — <b>his</b> bag, телефон Анны — <b>her</b> phone.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Анна потеряла свой кошелёк.</span><span class=\"en\">Anna can't find <mark>her</mark> wallet.</span><span class=\"why\">владелец — Анна (she) → her</span></li>\n<li><span class=\"ru\">Это машина моего брата. Его машина новая.</span><span class=\"en\">This is my brother's car. <mark>His</mark> car is new.</span><span class=\"why\">владелец — брат (he) → his</span></li>\n<li><span class=\"ru\">У собаки есть имя. Её зовут Рекс.</span><span class=\"en\">The dog has a name. <mark>Its</mark> name is Rex.</span><span class=\"why\">владелец — собака (it) → its</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>its (чей?) и it's (= it is) — разные слова. Подробно — в уроке 1, тема 8: <span class=\"no\">it's name</span> <span class=\"yes\">its name ✔</span></span><span>«Свой» по-английски — тоже my / his / her… : <span class=\"no\">I love self car.</span> <span class=\"yes\">I love my car. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>its name · mother's car = her car · Sasha's birthday = his birthday</span></div>","groups":[{"title":"Выберите слово","items":[{"t":"choice","q":"Tom, is this ___ jacket?","o":["you","your","yours"],"a":"your","ex":"Перед предметом (jacket) → your."},{"t":"choice","q":"Maria loves ___ new necklace.","o":["his","her","their"],"a":"her","ex":"Владелец Maria (she) → her."},{"t":"choice","q":"My brother can't find ___ keys.","o":["his","her","its"],"a":"his","ex":"Владелец brother (he) → his."},{"t":"choice","q":"We love ___ new flat.","o":["our","their","your"],"a":"our","ex":"we → our."},{"t":"choice","q":"The company changed ___ logo.","o":["it's","its","his"],"a":"its","ex":"Компания — it → its. it's = it is."},{"t":"choice","q":"My parents sold ___ car.","o":["theirs","their","they"],"a":"their","ex":"they → their, перед предметом."},{"t":"choice","q":"I use ___ laptop every day.","o":["my","mine","me"],"a":"my","ex":"Перед предметом → my."}]},{"title":"Замените имя на слово «чей»","items":[{"t":"input","q":"This is Anna's bag. → This is ___ bag.","a":["her"],"ex":"Anna → she → her.","p":"Впишите одно слово","h":"Anna — она."},{"t":"input","q":"Where is Tom's phone? → Where is ___ phone?","a":["his"],"ex":"Tom → he → his.","p":"Впишите одно слово","h":"Tom — он."},{"t":"input","q":"Jack and Linda's house is big. → ___ house is big.","a":["Their"],"ex":"Jack and Linda → they → their.","p":"Впишите одно слово","h":"Они."},{"t":"input","q":"The cat's bowl is empty. → ___ bowl is empty.","a":["Its"],"ex":"cat → it → its (без апострофа).","p":"Впишите одно слово","h":"Кошка — it."}]}]},{"id":"mine","nav":"mine · yours","eyebrow":"Тема 4 · притяжательные слова","title":"mine, yours, hers… — без предмета","theory":"<p>Когда предмет уже понятен и мы его не повторяем, вместо <b>my / your…</b> говорим <b>mine / yours…</b>. После них существительного <b>нет</b>.</p>\n<div class=\"compare\"><div><span class=\"en\">It's my house.</span><span class=\"ru\">Это мой дом.</span><span class=\"small\">my + предмет</span></div><div><span class=\"en\">This house is mine.</span><span class=\"ru\">Этот дом — мой.</span><span class=\"small\">mine в конце, без предмета</span></div></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Перед предметом</th><th>Без предмета</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>my</td><td><mark>mine</mark></td><td>The phone is mine.</td></tr>\n<tr><td>your</td><td><mark>yours</mark></td><td>Is this sweater yours?</td></tr>\n<tr><td>his</td><td><mark>his</mark></td><td>The cap is his.</td></tr>\n<tr><td>her</td><td><mark>hers</mark></td><td>They're hers.</td></tr>\n<tr><td>our</td><td><mark>ours</mark></td><td>That charger is ours.</td></tr>\n<tr><td>their</td><td><mark>theirs</mark></td><td>Those gloves are theirs.</td></tr>\n</tbody></table></div>\n<p>Запомнить просто: почти везде добавляется <b>-s</b> (yours, hers, ours, theirs). Исключения: <b>mine</b> и <b>his</b> (не меняется).</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">— Это твоя кепка? — Да, моя.</span><span class=\"en\">— Is this your cap? — Yes, it's <mark>mine</mark>.</span></li>\n<li><span class=\"ru\">Эти серьги её.</span><span class=\"en\">These earrings are <mark>hers</mark>.</span><span class=\"why\">her earrings → hers</span></li>\n<li><span class=\"ru\">Моя кепка здесь, а твоя там.</span><span class=\"en\">My cap is here, but <mark>yours</mark> is there.</span><span class=\"why\">yours = your cap</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Апострофа нет: <span class=\"no\">your's, her's, their's</span> <span class=\"yes\">yours, hers, theirs ✔</span></span><span>Не путайте форму: <span class=\"no\">Is this sweater your?</span> <span class=\"yes\">Is this sweater yours? ✔</span></span><span>После mine / yours предмет не ставится: <span class=\"no\">It's mine car.</span> <span class=\"yes\">It's my car. ✔</span> или <span class=\"yes\">The car is mine. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>It's my house. This is his idea. · It's my house — this house is mine</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"Is this sweater ___?","o":["your","yours","you"],"a":"yours","ex":"После слова «чей» нет предмета → yours.","b":{"your":"your нужен только перед предметом: your sweater."}},{"t":"choice","q":"A: That's my notebook. B: No, it isn't. It's ___!","o":["my","mine","me"],"a":"mine","ex":"В конце, без предмета → mine."},{"t":"choice","q":"These gloves are ___. (she)","o":["her","hers","she's"],"a":"hers","ex":"she → hers."},{"t":"choice","q":"Whose driving licence is this? — It's ___. (he)","o":["his","him","he's"],"a":"his","ex":"he → his (не меняется)."},{"t":"choice","q":"That phone charger is ___. (we)","o":["our","ours","us"],"a":"ours","ex":"we → ours."},{"t":"choice","q":"Are those earrings ___? (they)","o":["their","theirs","them"],"a":"theirs","ex":"they → theirs."},{"t":"choice","q":"This cap is mine, but that one's ___.","o":["your","yours","you're"],"a":"yours","ex":"that one = та кепка, предмета после слова нет → yours."}]},{"title":"Перепишите с mine, yours, hers… (как в домашнем задании)","items":[{"t":"input","q":"They're Janice's earrings.","a":["They're hers.","They are hers."],"ex":"Janice → she → hers.","p":"Замените с помощью hers, his, theirs…"},{"t":"input","q":"That's James's skateboard.","a":["That's his.","That is his.","It's his."],"ex":"James → he → his.","p":"Замените с помощью hers, his, theirs…"},{"t":"input","q":"Is this your cap?","a":["Is this yours?","Is it yours?"],"ex":"your cap → yours.","p":"Замените с помощью hers, his, theirs…"},{"t":"input","q":"It's Kate and Nathan's phone number.","a":["It's theirs.","It is theirs."],"ex":"Kate and Nathan → they → theirs.","p":"Замените с помощью hers, his, theirs…"},{"t":"input","q":"Are these my books?","a":["Are these mine?","Are they mine?"],"ex":"my books → mine.","p":"Замените с помощью hers, his, theirs…"},{"t":"input","q":"It's Fiona's handbag.","a":["It's hers.","It is hers."],"ex":"Fiona → she → hers.","p":"Замените с помощью hers, his, theirs…"},{"t":"input","q":"Are they our sandwiches?","a":["Are they ours?","Are these ours?"],"ex":"our sandwiches → ours.","p":"Замените с помощью hers, his, theirs…"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"Is this sweater your?","w":3,"c":"yours","ex":"В конце, без предмета → yours."},{"t":"fix","q":"These gloves are my.","w":3,"c":"mine","ex":"Без предмета → mine."},{"t":"fix","q":"This make-up is they're.","w":3,"c":"theirs","ex":"they're = they are. «Их» без предмета → theirs."},{"t":"fix","q":"These notebooks are their.","w":3,"c":"theirs","ex":"Без предмета → theirs."}]}]},{"id":"whose","nav":"whose · 's","eyebrow":"Тема 5 · вопрос и ответ","title":"Whose is it? — Чьё это? It's Harry's.","theory":"<h3>Whose — чей?</h3>\n<div class=\"formula\"><span class=\"slot be\">Whose</span><span class=\"plus\">+</span><span class=\"slot\">(предмет)</span><span class=\"plus\">+</span><span class=\"slot\">is · are</span><span class=\"plus\">+</span><span class=\"slot\">this / these…</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Чья это кепка?</span><span class=\"en\"><mark>Whose</mark> cap is this?</span><span class=\"why\">один предмет → is</span></li>\n<li><span class=\"ru\">Чьи это наушники?</span><span class=\"en\"><mark>Whose</mark> headphones are these?</span><span class=\"why\">несколько → are</span></li>\n<li><span class=\"ru\">Чьё это?</span><span class=\"en\"><mark>Whose</mark> is it?</span><span class=\"why\">предмет можно не называть</span></li>\n</ul>\n<h3>'s — принадлежность человеку</h3>\n<p>Вместо «блокнот Гарри» говорим «Гарри's блокнот»: <b>имя + 's + предмет</b>.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кому принадлежит</th><th>Как сказать</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>одному человеку</td><td>имя + <mark>'s</mark></td><td>Harry<mark>'s</mark> notebook · my mother<mark>'s</mark> car</td></tr>\n<tr><td>двум людям вместе</td><td>'s только у последнего</td><td>Harry and Sally<mark>'s</mark> flat</td></tr>\n<tr><td>слову на -s во мн. числе</td><td>только апостроф <mark>'</mark></td><td>my parent<mark>s'</mark> car</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">— Чей это блокнот? — Гарри.</span><span class=\"en\">— Whose notebook is this? — It's <mark>Harry's</mark>.</span><span class=\"why\">в ответе предмет не повторяем</span></li>\n<li><span class=\"ru\">Сегодня день рождения Саши.</span><span class=\"en\">It's <mark>Sasha's</mark> birthday today.</span><span class=\"why\">= his birthday</span></li>\n<li><span class=\"ru\">Машина мамы — её машина.</span><span class=\"en\">My <mark>mother's</mark> car = her car</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Whose (чей?) и Who's (= Who is, кто?) звучат одинаково: <span class=\"no\">Who's wallet is this?</span> <span class=\"yes\">Whose wallet is this? ✔</span></span><span>Без апострофа получается «много Салли»: <span class=\"no\">Those earrings are Sallys.</span> <span class=\"yes\">Those earrings are Sally's. ✔</span></span><span>Не переводите «of»: <span class=\"no\">the car of my mother</span> <span class=\"yes\">my mother's car ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>Whose is it? Whose — чей? · 's: mother's car = her car · Sasha's birthday = his birthday</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"___ earrings are these?","o":["Who","Whose","Who's"],"a":"Whose","ex":"Чьи? → Whose.","b":{"Who":"Who — кто. Нужно «чьи» → Whose.","Who's":"Who's = Who is. Нужно Whose."}},{"t":"choice","q":"Whose notebook ___ this?","o":["is","are"],"a":"is","ex":"notebook — один → is."},{"t":"choice","q":"Whose gloves ___ these?","o":["is","are"],"a":"are","ex":"gloves — несколько → are."},{"t":"choice","q":"A: Whose phone charger is this? B: It's ___.","o":["Anna","Anna's","Annas"],"a":"Anna's","ex":"Принадлежит Анне → Anna's."},{"t":"choice","q":"It's my ___ car.","o":["parents'","parent's","parents's"],"a":"parents'","ex":"Двое родителей: parents + ' → parents'.","b":{"parent's":"Так пишут про одного родителя. Родителей двое → parents'.","parents's":"После -s во множественном числе ставим только апостроф."}},{"t":"choice","q":"This is ___ flat. (Jack and Linda живут вместе)","o":["Jack's and Linda's","Jack and Linda's","Jack and Lindas"],"a":"Jack and Linda's","ex":"Общая квартира → 's только у последнего имени."}]},{"title":"Задайте вопрос с whose","items":[{"t":"input","q":"(this / cap)","a":["Whose cap is this?","Whose is this cap?"],"ex":"Whose + cap + is + this?","p":"Спросите, чья это вещь"},{"t":"input","q":"(these / keys)","a":["Whose keys are these?","Whose are these keys?"],"ex":"keys — несколько → are these.","p":"Спросите, чья это вещь"},{"t":"input","q":"(that / laptop)","a":["Whose laptop is that?","Whose is that laptop?"],"ex":"Whose + laptop + is + that?","p":"Спросите, чья это вещь"}]},{"title":"Соберите предложение","items":[{"t":"order","w":["this","is","whose","sweater"],"a":["Whose sweater is this?","Whose is this sweater?"],"ex":"Whose + sweater + is + this?"},{"t":"order","w":["Harry's","this","notebook","is"],"a":["This notebook is Harry's."],"ex":"Предмет + is + Harry's."},{"t":"order","w":["mother's","car","it's","my"],"a":["It's my mother's car."],"ex":"my mother's + car."},{"t":"order","w":["are","yours","these","gloves"],"a":["Are these gloves yours?"],"ex":"Are + these gloves + yours?"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"Who's wallet is this?","w":0,"c":"Whose","ex":"Чей? → Whose. Who's = Who is."},{"t":"fix","q":"Those earrings are Sallys.","w":3,"c":"Sally's","ex":"Принадлежность → апостроф: Sally's."},{"t":"fix","q":"Whose necklace are this?","w":2,"c":"is","ex":"necklace — один предмет → is."}]}]},{"id":"words","nav":"Фразы с доски","eyebrow":"Тема 6 · фразы со стикеров","title":"Фразы с ваших стикеров","theory":"<h3>inside / outside — внутри / снаружи</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Бабушка на улице.</span><span class=\"en\">My grandma <mark>is outside</mark>.</span><span class=\"why\">to be outside — быть снаружи, на улице</span></li>\n<li><span class=\"ru\">Давай останемся в доме, идёт дождь.</span><span class=\"en\">Let's stay <mark>inside</mark>. It's raining.</span><span class=\"why\">inside — внутри, в помещении</span></li>\n</ul>\n<h3>pleasant / unpleasant — приятный / неприятный</h3>\n<p>Приставка <b>un-</b> делает слово противоположным: pleasant → <b>un</b>pleasant, comfortable → <b>un</b>comfortable, happy → <b>un</b>happy.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Наш сосед очень приятный.</span><span class=\"en\">Our neighbour is very <mark>pleasant</mark>.</span><span class=\"why\">pleasant — приятный</span></li>\n<li><span class=\"ru\">Погода сегодня неприятная.</span><span class=\"en\">The weather is <mark>unpleasant</mark> today.</span><span class=\"why\">un + pleasant</span></li>\n</ul>\n<h3>pleased — рад, доволен</h3>\n<p>Из текста про вечеринку: <b>I'm really pleased</b> — я очень рада. Это состояние человека, поэтому с to be: I'm pleased, she is pleased.</p>\n<h3>which = what — какой, который</h3>\n<p><b>Which</b> — когда выбираем из небольшого числа вариантов: <b>Which</b> objects do they mention? — Какие вещи (из списка) они называют?</p>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>to be outside · to be inside · pleasant / unpleasant · which = what</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"It's cold. Let's stay ___.","o":["inside","outside","unpleasant"],"a":"inside","ex":"Холодно — останемся внутри: inside."},{"t":"choice","q":"The children are ___ in the garden.","o":["inside","outside"],"a":"outside","ex":"in the garden — на улице → outside."},{"t":"choice","q":"The opposite of «pleasant» is ___.","o":["unpleasant","displeasant","nopleasant"],"a":"unpleasant","ex":"un + pleasant."},{"t":"choice","q":"«Я очень рада.» — I'm really ___.","o":["pleased","pleasant","please"],"a":"pleased","ex":"pleased — рад (о человеке). pleasant — приятный (о чём-то)."},{"t":"choice","q":"___ bag is yours, the red one or the black one?","o":["Which","Who","Whose"],"a":"Which","ex":"Выбор из двух вариантов → Which."}]}]},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"___ are my new sunglasses.","o":["This","These","That"],"a":"These","ex":"Тема 2: sunglasses — несколько, близко → These."},{"t":"choice","q":"Is that bag ___?","o":["your","yours","you"],"a":"yours","ex":"Тема 4: без предмета → yours."},{"t":"choice","q":"___ keys are these?","o":["Who's","Whose","Who"],"a":"Whose","ex":"Тема 5: чьи? → Whose."},{"t":"input","q":"Anna's scarf → ___ scarf","a":["her"],"ex":"Тема 3: Anna → her.","p":"Впишите одно слово","h":"Anna — она."},{"t":"fix","q":"This is my brother car.","w":3,"c":"brother's","ex":"Тема 5: принадлежность → brother's."},{"t":"choice","q":"My gloves ___ in my bag.","o":["is","are"],"a":"are","ex":"Тема 1: gloves — несколько → are."},{"t":"input","q":"These are Tom's shoes.","a":["These are his.","They're his.","They are his."],"ex":"Тема 4: Tom → his.","p":"Замените с помощью his, hers, theirs…"},{"t":"order","w":["is","whose","phone","that","charger"],"a":["Whose phone charger is that?","Whose is that phone charger?"],"ex":"Тема 5: Whose + phone charger + is + that?"},{"t":"choice","q":"The dog is hungry. ___ bowl is empty.","o":["It's","Its","His"],"a":"Its","ex":"Тема 3: собака — it → its."},{"t":"fix","q":"Those shoes is very expensive.","w":2,"c":"are","ex":"Тема 2: those + are."},{"t":"choice","q":"It's cold ___. Take your scarf.","o":["outside","inside","pleasant"],"a":"outside","ex":"Тема 6: на улице → outside."},{"t":"input","q":"This is ___ flat. (Jack and Linda)","a":["Jack and Linda's"],"ex":"Тема 5: общая квартира → 's у последнего имени.","p":"Впишите, чья квартира"}]}]}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 3: have got — у меня есть (7 sections, 85 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('have-got', 'have got — у меня есть', 'have got / has got, отрицания и вопросы, have и do you have, прилагательные для описания вещей', 3, $lesson${"sections":[{"id":"plus","nav":"have got","eyebrow":"Тема 1 · утверждение","title":"I've got, she's got — у меня есть, у неё есть","theory":"<p>По-русски говорим «<b>у меня есть</b> машина». По-английски наоборот: «<b>я имею</b> машину» — <b>I have got a car</b>. Так говорят о том, что у нас есть: вещи, семья, животные, внешность.</p>\n<div class=\"formula\"><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">have got · has got</span><span class=\"plus\">+</span><span class=\"slot\">что</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Полная форма</th><th>Коротко</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I / you / we / they</td><td>have got</td><td><mark>'ve got</mark></td><td>I've got a new phone.</td></tr>\n<tr><td>he / she / it</td><td>has got</td><td><mark>'s got</mark></td><td>She's got two sisters.</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">У меня есть брат.</span><span class=\"en\">I<mark>'ve got</mark> a brother.</span><span class=\"why\">семья</span></li>\n<li><span class=\"ru\">У неё новый мобильный.</span><span class=\"en\">She<mark>'s got</mark> a new mobile phone.</span><span class=\"why\">вещи</span></li>\n<li><span class=\"ru\">У нас есть собака.</span><span class=\"en\">We<mark>'ve got</mark> a dog.</span><span class=\"why\">животные</span></li>\n<li><span class=\"ru\">У него карие глаза.</span><span class=\"en\">He<mark>'s got</mark> brown eyes.</span><span class=\"why\">внешность</span></li>\n<li><span class=\"ru\">У моей квартиры есть сад.</span><span class=\"en\">My flat <mark>has got</mark> a garden.</span><span class=\"why\">flat = it → has</span></li>\n</ul>\n<h3>'s — это is или has?</h3>\n<p>Сокращение <b>'s</b> бывает двух видов. Смотрите, есть ли после него <b>got</b>.</p>\n<div class=\"compare\"><div><span class=\"en\">He's got a car.</span><span class=\"ru\">У него есть машина.</span><span class=\"small\">'s + got = has got</span></div><div><span class=\"en\">He's a good man.</span><span class=\"ru\">Он хороший человек.</span><span class=\"small\">'s без got = is</span></div></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>he / she / it — только has: <span class=\"no\">She have got a cat.</span> <span class=\"yes\">She has got a cat. ✔</span></span><span>Не забывайте got: <span class=\"no\">I've a car.</span> <span class=\"yes\">I've got a car. ✔</span></span><span>У всех, кроме he / she / it, сокращение 've: <span class=\"no\">Sara've got a bag.</span> <span class=\"yes\">Sara's got a bag. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>have got / has got — иметь · I have got a brother · /has got — у меня есть / у него есть</span></div>","groups":[{"title":"have got или has got?","items":[{"t":"choice","q":"I ___ a new laptop.","o":["have got","has got"],"a":"have got","ex":"I → have got."},{"t":"choice","q":"My sister ___ a beautiful necklace.","o":["have got","has got"],"a":"has got","ex":"sister = she → has got."},{"t":"choice","q":"We ___ two cats.","o":["have got","has got"],"a":"have got","ex":"we → have got."},{"t":"choice","q":"Tom ___ blue eyes.","o":["have got","has got"],"a":"has got","ex":"Tom = he → has got."},{"t":"choice","q":"My parents ___ a big house.","o":["have got","has got"],"a":"have got","ex":"parents = they → have got."},{"t":"choice","q":"Our flat ___ a balcony.","o":["have got","has got"],"a":"has got","ex":"flat = it → has got."},{"t":"choice","q":"You ___ a lot of books!","o":["have got","has got"],"a":"have got","ex":"you → have got."}]},{"title":"Что значит 's?","items":[{"t":"choice","q":"She's got a new car. — 's = ___","o":["is","has"],"a":"has","ex":"После 's стоит got → has got."},{"t":"choice","q":"She's a doctor. — 's = ___","o":["is","has"],"a":"is","ex":"got нет → is: She is a doctor."},{"t":"choice","q":"It's heavy. — 's = ___","o":["is","has"],"a":"is","ex":"It is heavy — «оно тяжёлое»."},{"t":"choice","q":"He's got a dog. — 's = ___","o":["is","has"],"a":"has","ex":"'s + got → has got."}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"She have got two brothers.","w":1,"c":"has","ex":"she → has got."},{"t":"fix","q":"They has got a garden.","w":1,"c":"have","ex":"they → have got."},{"t":"fix","q":"I've a new camera.","w":0,"c":"I've got","ex":"have got — нужен got: I've got."}]}]},{"id":"neg","nav":"haven't got","eyebrow":"Тема 2 · отрицание","title":"haven't got, hasn't got — у меня нет","theory":"<p>Чтобы сказать «у меня нет», ставим <b>not</b> после have / has. Got остаётся на месте.</p>\n<div class=\"formula\"><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">haven't got · hasn't got</span><span class=\"plus\">+</span><span class=\"slot\">что</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Полная форма</th><th>Коротко</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I / you / we / they</td><td>have not got</td><td><mark>haven't got</mark></td><td>I haven't got a car.</td></tr>\n<tr><td>he / she / it</td><td>has not got</td><td><mark>hasn't got</mark></td><td>She hasn't got big ears.</td></tr>\n</tbody></table></div>\n<h3>any — в отрицаниях и вопросах</h3>\n<p>С предметами во множественном числе в отрицании и вопросе ставим <b>any</b>: «нет никаких», «есть ли какие-нибудь».</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">У меня нет братьев.</span><span class=\"en\">I <mark>haven't got any</mark> brothers.</span><span class=\"why\">haven't got + any + мн. число</span></li>\n<li><span class=\"ru\">У него сейчас нет с собой камеры.</span><span class=\"en\">He <mark>hasn't got</mark> a camera with him.</span><span class=\"why\">одна вещь → a</span></li>\n<li><span class=\"ru\">У нас нет времени.</span><span class=\"en\">We <mark>haven't got</mark> time.</span><span class=\"why\">time — нельзя посчитать, без a</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После he / she / it — hasn't: <span class=\"no\">He haven't got a bike.</span> <span class=\"yes\">He hasn't got a bike. ✔</span></span><span>В отрицании с мн. числом нужен any, а не some: <span class=\"no\">I haven't got some sisters.</span> <span class=\"yes\">I haven't got any sisters. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>I haven't got any brothers · We haven't got · He hasn't got a car and he hasn't got a bike</span></div>","groups":[{"title":"Выберите правильную форму","items":[{"t":"choice","q":"I ___ a pen. Can I use yours?","o":["haven't got","hasn't got"],"a":"haven't got","ex":"I → haven't got."},{"t":"choice","q":"My brother ___ a car.","o":["haven't got","hasn't got"],"a":"hasn't got","ex":"brother = he → hasn't got."},{"t":"choice","q":"We haven't got ___ eggs.","o":["some","any","a"],"a":"any","ex":"Отрицание + мн. число → any."},{"t":"choice","q":"She ___ any pets.","o":["haven't got","hasn't got"],"a":"hasn't got","ex":"she → hasn't got."},{"t":"choice","q":"They haven't got ___ garden.","o":["a","any","some"],"a":"a","ex":"garden — одна вещь → a."}]},{"title":"Сделайте предложение отрицательным (как в домашнем задании)","items":[{"t":"input","q":"We've got a large car.","a":["We haven't got a large car.","We have not got a large car."],"ex":"We've got → We haven't got.","p":"Сделайте отрицание"},{"t":"input","q":"I've got a camera with me.","a":["I haven't got a camera with me.","I have not got a camera with me."],"ex":"I've got → I haven't got.","p":"Сделайте отрицание"},{"t":"input","q":"My flat has got a garden.","a":["My flat hasn't got a garden.","My flat has not got a garden."],"ex":"has got → hasn't got.","p":"Сделайте отрицание"},{"t":"input","q":"She's got a new phone.","a":["She hasn't got a new phone.","She has not got a new phone."],"ex":"She's got = She has got → She hasn't got.","p":"Сделайте отрицание"}]},{"title":"Сделайте предложение утвердительным","items":[{"t":"input","q":"Sara hasn't got a bag with her.","a":["Sara has got a bag with her.","Sara's got a bag with her."],"ex":"hasn't got → has got. Sara = she → has.","p":"Сделайте утверждение"},{"t":"input","q":"I haven't got time now.","a":["I have got time now.","I've got time now."],"ex":"haven't got → have got.","p":"Сделайте утверждение"}]}]},{"id":"q","nav":"Have you got…?","eyebrow":"Тема 3 · вопрос","title":"Have you got…? — Yes, I have. / No, I haven't.","theory":"<p>В вопросе <b>Have / Has</b> выходит вперёд, а <b>got</b> остаётся после «кто».</p>\n<div class=\"formula\"><span class=\"slot be\">Have · Has</span><span class=\"plus\">+</span><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">got</span><span class=\"plus\">+</span><span class=\"slot\">что</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Да</th><th>Нет</th></tr></thead>\n<tbody>\n<tr><td><mark>Have</mark> you <mark>got</mark> a bike?</td><td>Yes, I have.</td><td>No, I haven't.</td></tr>\n<tr><td><mark>Has</mark> she <mark>got</mark> a sister?</td><td>Yes, she has.</td><td>No, she hasn't.</td></tr>\n<tr><td><mark>Have</mark> they <mark>got</mark> a car?</td><td>Yes, they have.</td><td>No, they haven't.</td></tr>\n</tbody></table></div>\n<p>В коротком ответе <b>got не нужен</b>: только Yes, I have / No, I haven't.</p>\n<h3>Вопросы со словами</h3>\n<div class=\"formula\"><span class=\"slot\">What / How many…</span><span class=\"plus\">+</span><span class=\"slot be\">have · has</span><span class=\"plus\">+</span><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">got</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Какая у тебя машина?</span><span class=\"en\"><mark>What</mark> car <mark>have</mark> you <mark>got</mark>?</span></li>\n<li><span class=\"ru\">Сколько у неё детей?</span><span class=\"en\"><mark>How many</mark> children <mark>has</mark> she <mark>got</mark>?</span></li>\n<li><span class=\"ru\">Какой у тебя телефон?</span><span class=\"en\"><mark>What</mark> phone <mark>have</mark> you <mark>got</mark>?</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>В коротком ответе без got: <span class=\"no\">No, I haven't got, sorry.</span> <span class=\"yes\">No, I haven't, sorry. ✔</span></span><span>Не смешивайте do и got: <span class=\"no\">Do you have got a car?</span> <span class=\"yes\">Have you got a car? ✔</span> или <span class=\"yes\">Do you have a car? ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>Have you got a brother? · Yes, he's got a dog · Have you got the password? · What car / What pet / What phone</span></div>","groups":[{"title":"Выберите Have или Has","items":[{"t":"choice","q":"___ you got a minute?","o":["Have","Has"],"a":"Have","ex":"you → Have."},{"t":"choice","q":"___ Evan got any sisters?","o":["Have","Has"],"a":"Has","ex":"Evan = he → Has."},{"t":"choice","q":"___ they got a car?","o":["Have","Has"],"a":"Have","ex":"they → Have."},{"t":"choice","q":"___ your flat got a balcony?","o":["Have","Has"],"a":"Has","ex":"flat = it → Has."}]},{"title":"Выберите короткий ответ","items":[{"t":"choice","q":"Have you got a laptop? — Yes, ___.","o":["I have","I've got","I do"],"a":"I have","ex":"Короткий ответ без got: Yes, I have.","b":{"I've got":"В кратком «да» сокращение и got не нужны: Yes, I have.","I do":"Вопрос с have got → ответ с have."}},{"t":"choice","q":"Has Maisie got any children? — Yes, ___.","o":["she has","she have","she's"],"a":"she has","ex":"Maisie = she → Yes, she has."},{"t":"choice","q":"Have they got a garden? — No, ___.","o":["they haven't","they haven't got","they don't"],"a":"they haven't","ex":"Без got: No, they haven't."},{"t":"choice","q":"Has he got a sister? — No, ___.","o":["he hasn't","he haven't","he isn't"],"a":"he hasn't","ex":"he → hasn't."}]},{"title":"Задайте вопрос (как в домашнем задании)","items":[{"t":"input","q":"you / a car?","a":["Have you got a car?"],"ex":"Have + you + got + a car?","p":"Составьте вопрос с have got"},{"t":"input","q":"they / a garden?","a":["Have they got a garden?"],"ex":"Have + they + got + a garden?","p":"Составьте вопрос с have got"},{"t":"input","q":"she / any brothers or sisters?","a":["Has she got any brothers or sisters?"],"ex":"she → Has she got…?","p":"Составьте вопрос с have got"},{"t":"input","q":"you / the password?","a":["Have you got the password?"],"ex":"Have you got the password?","p":"Составьте вопрос с have got"},{"t":"input","q":"Scott / any pets?","a":["Has Scott got any pets?"],"ex":"Scott = he → Has Scott got any pets?","p":"Составьте вопрос с have got"}]},{"title":"Соберите вопрос","items":[{"t":"order","w":["car","have","got","what","you"],"a":["What car have you got?"],"ex":"What car + have + you + got?"},{"t":"order","w":["she","children","how","many","has","got"],"a":["How many children has she got?"],"ex":"How many children + has + she + got?"},{"t":"order","w":["has","your","bike","a","brother","got"],"a":["Has your brother got a bike?"],"ex":"Has + your brother + got + a bike?"}]}]},{"id":"have","nav":"have и do you have","eyebrow":"Тема 4 · два способа","title":"I've got a car = I have a car","theory":"<p>«У меня есть» можно сказать двумя способами. Смысл одинаковый, различаются только отрицание и вопрос.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th></th><th>have got</th><th>have</th></tr></thead>\n<tbody>\n<tr><td>+</td><td>I<mark>'ve got</mark> a car.<br>She<mark>'s got</mark> a car.</td><td>I <mark>have</mark> a car.<br>She <mark>has</mark> a car.</td></tr>\n<tr><td>−</td><td>I <mark>haven't got</mark> a car.<br>She <mark>hasn't got</mark> a car.</td><td>I <mark>don't have</mark> a car.<br>She <mark>doesn't have</mark> a car.</td></tr>\n<tr><td>?</td><td><mark>Have</mark> you <mark>got</mark> a car?<br><mark>Has</mark> she <mark>got</mark> a car?</td><td><mark>Do</mark> you <mark>have</mark> a car?<br><mark>Does</mark> she <mark>have</mark> a car?</td></tr>\n<tr><td>Ответ</td><td>Yes, I have. / No, she hasn't.</td><td>Yes, I do. / No, she doesn't.</td></tr>\n</tbody></table></div>\n<p><b>have got</b> чаще звучит в британском разговорном английском. <b>have</b> с do / does — универсальный вариант, его понимают везде. Подробнее про do / does — в уроках 4 и 5.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Выберите один способ и не смешивайте: <span class=\"no\">Does Scott has got any pets?</span> <span class=\"yes\">Has Scott got any pets? ✔</span> <span class=\"yes\">Does Scott have any pets? ✔</span></span><span>После doesn't и does — have, а не has: <span class=\"no\">She doesn't has a car.</span> <span class=\"yes\">She doesn't have a car. ✔</span></span><span>Возраст — не через have: <span class=\"no\">I have 30 years.</span> <span class=\"yes\">I'm 30. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>to have / has — иметь: I have a car · I don't have a car · Do you have a car?</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"___ you have a pen?","o":["Do","Have","Are"],"a":"Do","ex":"have без got → вопрос с Do."},{"t":"choice","q":"___ you got a pen?","o":["Do","Have","Are"],"a":"Have","ex":"С got → Have you got…?"},{"t":"choice","q":"She doesn't ___ a car.","o":["has","have","has got"],"a":"have","ex":"После doesn't — have."},{"t":"choice","q":"Do you have any brothers? — No, I ___.","o":["don't","haven't","am not"],"a":"don't","ex":"Вопрос с Do → ответ No, I don't."},{"t":"choice","q":"Have you got any brothers? — No, I ___.","o":["don't","haven't","am not"],"a":"haven't","ex":"Вопрос с Have… got → ответ No, I haven't."},{"t":"choice","q":"«Мне 25 лет.»","o":["I have 25 years.","I'm 25.","I've got 25 years."],"a":"I'm 25.","ex":"Возраст — через to be."}]},{"title":"Скажите то же самое по-другому","items":[{"t":"input","q":"I haven't got a car.","a":["I don't have a car.","I do not have a car."],"ex":"haven't got → don't have.","p":"Перепишите с don't / doesn't have"},{"t":"input","q":"Has she got a sister?","a":["Does she have a sister?"],"ex":"Has she got → Does she have.","p":"Перепишите с do / does"},{"t":"input","q":"Do they have a garden?","a":["Have they got a garden?"],"ex":"Do they have → Have they got.","p":"Перепишите с have got"},{"t":"input","q":"He doesn't have a bike.","a":["He hasn't got a bike.","He has not got a bike."],"ex":"doesn't have → hasn't got.","p":"Перепишите с have got"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"Does Scott has any pets?","w":2,"c":"have","ex":"После Does — have."},{"t":"fix","q":"Do you have got a car?","w":0,"c":"Have","ex":"С got вопрос начинается с Have: Have you got a car?"},{"t":"fix","q":"She doesn't has a dog.","w":2,"c":"have","ex":"После doesn't — have."}]}]},{"id":"adj","nav":"Описание вещей","eyebrow":"Тема 5 · лексика","title":"Какая это вещь? Прилагательные","theory":"<p>Слова из урока «Special things» — ими описывают предметы.</p>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Размер и форма</h4><ul><li>large / big — большой</li><li>small — маленький</li><li>round — круглый</li><li>square — квадратный</li><li>heavy — тяжёлый</li><li>light — лёгкий</li></ul></div><div class=\"ng\"><h4>Возраст и состояние</h4><ul><li>old — старый</li><li>new — новый</li><li>modern — современный</li><li>broken — сломанный</li><li>soft — мягкий</li><li>comfortable — удобный</li></ul></div></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Цвет и материал</h4><ul><li>brown — коричневый</li><li>gold — золотой</li><li>silver — серебряный</li></ul></div><div class=\"ng\"><h4>Оценка</h4><ul><li>beautiful — красивый</li><li>useful — полезный</li><li>special — особенный</li><li>handsome / good-looking — красивый (о человеке)</li></ul></div></div>\n<h3>Где ставить прилагательное</h3>\n<p>Прилагательное стоит <b>перед</b> предметом или <b>после to be</b>. Оно не меняется во множественном числе.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">У меня тяжёлая сумка.</span><span class=\"en\">I've got a <mark>heavy</mark> bag.</span><span class=\"why\">перед предметом</span></li>\n<li><span class=\"ru\">Сумка тяжёлая и не очень удобная.</span><span class=\"en\">It's <mark>heavy</mark> and it isn't very <mark>comfortable</mark>.</span><span class=\"why\">после is</span></li>\n<li><span class=\"ru\">Это красивые серьги.</span><span class=\"en\">They're <mark>beautiful</mark> earrings.</span><span class=\"why\">без -s: не beautifuls</span></li>\n<li><span class=\"ru\">Мой ноутбук сломан, я не могу им пользоваться.</span><span class=\"en\">My laptop is <mark>broken</mark>. I can't use it.</span></li>\n</ul>\n<h3>Противоположности</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Противоположное</th></tr></thead>\n<tbody>\n<tr><td>old</td><td>new · modern</td></tr>\n<tr><td>heavy</td><td>light</td></tr>\n<tr><td>large / big</td><td>small</td></tr>\n<tr><td>comfortable</td><td><mark>un</mark>comfortable</td></tr>\n<tr><td>useful</td><td>use<mark>less</mark></td></tr>\n</tbody></table></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Прилагательное не получает -s: <span class=\"no\">They are olds phones.</span> <span class=\"yes\">They are old phones. ✔</span></span><span>Порядок как в русском, но a / an — перед прилагательным: <span class=\"no\">I've got heavy a bag.</span> <span class=\"yes\">I've got a heavy bag. ✔</span></span><span>handsome и good-looking — о людях: <span class=\"yes\">He's handsome. ✔</span>, а о вещи — <span class=\"yes\">a beautiful watch ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>It is heavy and it is not very comfortable · handsome / good-looking · what can be beautiful?</span></div>","groups":[{"title":"Выберите слово (как в домашнем задании)","items":[{"t":"choice","q":"I love my teddy bear. He's really ___.","o":["soft","broken","square"],"a":"soft","ex":"Плюшевый мишка — мягкий: soft."},{"t":"choice","q":"My laptop is ___. I can't use it.","o":["useful","broken","light"],"a":"broken","ex":"Не могу пользоваться → сломан: broken."},{"t":"choice","q":"My new mobile is small, ___ and easy to use.","o":["heavy","light","square"],"a":"light","ex":"small и easy to use → лёгкий: light."},{"t":"choice","q":"A vocabulary notebook is very ___.","o":["useful","broken","round"],"a":"useful","ex":"Словарная тетрадь полезная: useful."},{"t":"choice","q":"My gloves are so ___. They feel very nice.","o":["comfortable","round","broken"],"a":"comfortable","ex":"Приятно носить → удобные: comfortable."},{"t":"choice","q":"Do you prefer the square table or the ___ one?","o":["round","soft","gold"],"a":"round","ex":"square — квадратный, противоположная форма — round."}]},{"title":"Напишите противоположное слово","items":[{"t":"input","q":"old →","a":["new","modern"],"ex":"old → new (или modern).","p":"Напишите противоположное прилагательное","h":"Начинается на n."},{"t":"input","q":"heavy →","a":["light"],"ex":"heavy → light.","p":"Напишите противоположное прилагательное","h":"Начинается на l."},{"t":"input","q":"small →","a":["large","big"],"ex":"small → large / big.","p":"Напишите противоположное прилагательное","h":"large или b…"},{"t":"input","q":"comfortable →","a":["uncomfortable"],"ex":"un + comfortable.","p":"Напишите противоположное прилагательное","h":"Приставка un-."}]},{"title":"Соберите предложение","items":[{"t":"order","w":["i've","watch","beautiful","got","gold","a"],"a":["I've got a beautiful gold watch."],"ex":"a + beautiful + gold + watch."},{"t":"order","w":["bag","is","old","heavy","my","and"],"a":["My bag is heavy and old."],"ex":"My bag + is + heavy and old."},{"t":"order","w":["she","new","got","has","bike","a","red"],"a":["She has got a new red bike."],"ex":"a + new + red + bike."}]}]},{"id":"words","nav":"Фразы с доски","eyebrow":"Тема 6 · фразы со стикеров","title":"Фразы с ваших стикеров","theory":"<h3>everything · everybody · everywhere</h3>\n<p><b>every</b> — каждый. Добавляем слово и получаем «всё, все, везде».</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Значение</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>every + thing</td><td><mark>everything</mark> — всё</td><td>Everything is OK.</td></tr>\n<tr><td>every + body / one</td><td><mark>everybody</mark> / everyone — все (люди)</td><td>Everybody is here.</td></tr>\n<tr><td>every + where</td><td><mark>everywhere</mark> — везде</td><td>My laptop is always with me — everywhere.</td></tr>\n</tbody></table></div>\n<p>После everything / everybody — глагол как с <b>he / she / it</b>: Everybody <b>is</b> happy (а не are).</p>\n<h3>the same as — такой же, как</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Сегодня всё так же, как вчера.</span><span class=\"en\">Today is <mark>the same as</mark> yesterday.</span></li>\n</ul>\n<h3>to lie — два значения</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я тебе не вру.</span><span class=\"en\">I don't <mark>lie</mark> to you.</span><span class=\"why\">lie — лгать</span></li>\n<li><span class=\"ru\">Кошка лежит на земле.</span><span class=\"en\">The cat <mark>is lying</mark> on the ground.</span><span class=\"why\">lie — лежать</span></li>\n</ul>\n<h3>special for — особенный для</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Ноутбук особенно важен для Ника.</span><span class=\"en\">The laptop is <mark>special for</mark> Nick.</span><span class=\"why\">Nick: «It's always with me»</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После everybody — is: <span class=\"no\">Everybody are here.</span> <span class=\"yes\">Everybody is here. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>everything / everybody / everywhere · the same as yesterday · to lie · Laptop is special for Nick · ring · chair · ground</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"«Всё хорошо.» — ___ is fine.","o":["Everything","Everybody","Everywhere"],"a":"Everything","ex":"всё (о вещах, делах) → everything."},{"t":"choice","q":"«Все пришли.» — ___ is here.","o":["Everything","Everybody","Everywhere"],"a":"Everybody","ex":"все люди → everybody."},{"t":"choice","q":"I take my phone ___.","o":["everything","everybody","everywhere"],"a":"everywhere","ex":"везде → everywhere."},{"t":"choice","q":"Everybody ___ happy today.","o":["is","are"],"a":"is","ex":"После everybody — is."},{"t":"choice","q":"My new bag is the same ___ yours.","o":["as","like","that"],"a":"as","ex":"the same as — такой же, как."},{"t":"choice","q":"«Не лги мне!» — Don't ___ to me!","o":["lie","lay","lying"],"a":"lie","ex":"lie — лгать."}]}]},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"My brother ___ a new motorbike.","o":["have got","has got"],"a":"has got","ex":"Тема 1: brother = he → has got."},{"t":"choice","q":"She's got long hair. — 's = ___","o":["is","has"],"a":"has","ex":"Тема 1: 's + got = has got."},{"t":"input","q":"They've got a dog.","a":["They haven't got a dog.","They have not got a dog."],"ex":"Тема 2: 've got → haven't got.","p":"Сделайте отрицание"},{"t":"choice","q":"Has your sister got a car? — Yes, ___.","o":["she has","she's got","she does"],"a":"she has","ex":"Тема 3: без got: Yes, she has."},{"t":"order","w":["you","any","got","or","have","brothers","sisters"],"a":["Have you got any brothers or sisters?"],"ex":"Тема 3: Have + you + got + any brothers or sisters?"},{"t":"fix","q":"Does she has a laptop?","w":2,"c":"have","ex":"Тема 4: после Does — have."},{"t":"input","q":"I don't have a bike.","a":["I haven't got a bike.","I have not got a bike."],"ex":"Тема 4: don't have → haven't got.","p":"Перепишите с have got"},{"t":"choice","q":"This chair is very ___. I love sitting in it.","o":["comfortable","broken","heavy"],"a":"comfortable","ex":"Тема 5: приятно сидеть → comfortable."},{"t":"fix","q":"I've got two olds watches.","w":3,"c":"old","ex":"Тема 5: прилагательное без -s."},{"t":"choice","q":"«Везде» — ___","o":["everything","everybody","everywhere"],"a":"everywhere","ex":"Тема 6: every + where."},{"t":"choice","q":"We haven't got ___ milk. Can you buy some?","o":["a","any","some"],"a":"any","ex":"Тема 2: в отрицании → any."},{"t":"input","q":"he / a big house?","a":["Has he got a big house?"],"ex":"Тема 3: he → Has he got…?","p":"Составьте вопрос с have got"}]}]}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 4: Present Simple: I, you, we, they (6 sections, 84 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('present-simple-i-you-we-they', 'Present Simple: I, you, we, they', 'что я делаю обычно, don''t и do, свободное время, always / never, at / on / in, дни и месяцы', 4, $lesson${"sections":[{"id":"plus","nav":"I work","eyebrow":"Тема 1 · утверждение","title":"I work, we live — что мы делаем обычно","theory":"<h3>Сначала: какие бывают слова</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Часть речи</th><th>Вопрос</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>глагол — verb (V)</td><td>что делать?</td><td>work, live, play</td></tr>\n<tr><td>существительное — noun</td><td>кто? что?</td><td>friend, book, weekend</td></tr>\n<tr><td>прилагательное — adjective</td><td>какой?</td><td>busy, free, interesting</td></tr>\n<tr><td>наречие — adverb</td><td>как? как часто?</td><td>often, never, well</td></tr>\n</tbody></table></div>\n<p>Present Simple говорит о том, что происходит <b>обычно, регулярно</b> или <b>всегда правда</b>: привычки, распорядок, факты о себе.</p>\n<div class=\"formula\"><span class=\"slot\">I · you · we · they</span><span class=\"plus\">+</span><span class=\"slot be\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span></div>\n<p>С I, you, we, they глагол берём <b>как в словаре</b>, ничего не добавляем.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я работаю из дома.</span><span class=\"en\">I <mark>work</mark> from home.</span><span class=\"why\">постоянно, это факт</span></li>\n<li><span class=\"ru\">Мы ходим в кино каждую пятницу.</span><span class=\"en\">We <mark>go</mark> to the cinema every Friday.</span><span class=\"why\">регулярно</span></li>\n<li><span class=\"ru\">Они живут в Берлине.</span><span class=\"en\">They <mark>live</mark> in Berlin.</span><span class=\"why\">факт</span></li>\n<li><span class=\"ru\">Я много читаю.</span><span class=\"en\">I <mark>read</mark> a lot of books.</span><span class=\"why\">привычка</span></li>\n</ul>\n<h3>to be или глагол-действие?</h3>\n<p>Вспомните урок 1: сказуемое одно. Если есть глагол-действие, <b>am / is / are не нужны</b>.</p>\n<div class=\"compare\"><div><span class=\"en\">I am busy.</span><span class=\"ru\">Я занят.</span><span class=\"small\">нет действия → am</span></div><div><span class=\"en\">I work a lot.</span><span class=\"ru\">Я много работаю.</span><span class=\"small\">есть действие work → без am</span></div></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Не ставьте am / are рядом с глаголом: <span class=\"no\">I am work from home.</span> <span class=\"yes\">I work from home. ✔</span></span><span>Не добавляйте -ing, если речь о привычке: <span class=\"no\">I working every day.</span> <span class=\"yes\">I work every day. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>Present Simple · I / you / we / they V (verb) · (+) I go / we want / they like / you take · I work from home</span></div>","groups":[{"title":"Нужен ли am / are? «—» значит «ничего не нужно»","items":[{"t":"choice","q":"I ___ live in Moscow.","o":["am","—"],"a":"—","ex":"live — глагол-действие, am не нужен."},{"t":"choice","q":"We ___ very busy at work.","o":["are","—"],"a":"are","ex":"busy — не действие, нужен are."},{"t":"choice","q":"They ___ play tennis on Sundays.","o":["are","—"],"a":"—","ex":"play — действие, are не нужен."},{"t":"choice","q":"I ___ tired in the evenings.","o":["am","—"],"a":"am","ex":"tired — состояние, нужен am."},{"t":"choice","q":"You ___ cook very well!","o":["are","—"],"a":"—","ex":"cook — действие."}]},{"title":"Какое предложение правильное?","items":[{"t":"choice","q":"«Я работаю в офисе.»","o":["I work in an office.","I am work in an office.","I working in an office."],"a":"I work in an office.","ex":"Одно сказуемое — work.","b":{"I am work in an office.":"work уже сказуемое, am лишний.","I working in an office.":"Для привычки -ing не нужен."}},{"t":"choice","q":"«Мы часто готовим пасту.»","o":["We often cook pasta.","We are often cook pasta.","We often cooking pasta."],"a":"We often cook pasta.","ex":"Глагол в словарной форме: cook."},{"t":"choice","q":"«Мои друзья живут рядом.»","o":["My friends live near me.","My friends are live near me.","My friends lives near me."],"a":"My friends live near me.","ex":"friends = they → live, без -s."}]},{"title":"Какая это часть речи?","items":[{"t":"choice","q":"weekend — это ___","o":["noun","verb","adjective"],"a":"noun","ex":"weekend — выходные, отвечает на «что?» → noun."},{"t":"choice","q":"play — это ___","o":["noun","verb","adverb"],"a":"verb","ex":"play — играть, «что делать?» → verb."},{"t":"choice","q":"busy — это ___","o":["verb","adjective","adverb"],"a":"adjective","ex":"busy — занятой, «какой?» → adjective."},{"t":"choice","q":"often — это ___","o":["noun","adjective","adverb"],"a":"adverb","ex":"often — часто, «как часто?» → adverb."}]}]},{"id":"neg","nav":"don't · do","eyebrow":"Тема 2 · отрицание и вопрос","title":"I don't work. Do you work?","theory":"<h3>Отрицание: don't</h3>\n<p>Ставим <b>don't</b> (= do not) перед глаголом. Сам глагол не меняется.</p>\n<div class=\"formula\"><span class=\"slot\">I · you · we · they</span><span class=\"plus\">+</span><span class=\"slot be\">don't</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я не смотрю телевизор.</span><span class=\"en\">I <mark>don't watch</mark> TV.</span></li>\n<li><span class=\"ru\">У нас мало свободного времени.</span><span class=\"en\">We <mark>don't have</mark> a lot of free time.</span><span class=\"why\">дословно: у нас нет много времени</span></li>\n<li><span class=\"ru\">Они не любят овощи.</span><span class=\"en\">They <mark>don't like</mark> vegetables.</span></li>\n</ul>\n<h3>Вопрос: Do</h3>\n<div class=\"formula\"><span class=\"slot be\">Do</span><span class=\"plus\">+</span><span class=\"slot\">you · we · they</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Да</th><th>Нет</th></tr></thead>\n<tbody>\n<tr><td><mark>Do</mark> you like coffee?</td><td>Yes, I do.</td><td>No, I don't.</td></tr>\n<tr><td><mark>Do</mark> they live here?</td><td>Yes, they do.</td><td>No, they don't.</td></tr>\n</tbody></table></div>\n<p>В коротком ответе глагол не повторяем: <b>Yes, I do</b>, а не Yes, I like.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После don't — глагол, а не got: <span class=\"no\">I don't got a car.</span> <span class=\"yes\">I don't have a car. ✔</span> <span class=\"yes\">I haven't got a car. ✔</span></span><span>Not без do не работает: <span class=\"no\">I not like it.</span> <span class=\"no\">I no like it.</span> <span class=\"yes\">I don't like it. ✔</span></span><span>В вопросе нужен Do: <span class=\"no\">You like coffee?</span> <span class=\"yes\">Do you like coffee? ✔</span></span><span>Не путайте с to be: <span class=\"no\">Do you are tired?</span> <span class=\"yes\">Are you tired? ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>(−) we don't like · (?) Do you have? Do you want? · Yes, I do / No, I don't</span></div>","groups":[{"title":"Выберите правильную форму","items":[{"t":"choice","q":"I ___ coffee before bed.","o":["don't drink","not drink","am not drink"],"a":"don't drink","ex":"Отрицание: don't + глагол."},{"t":"choice","q":"___ you play the guitar?","o":["Do","Are","Have"],"a":"Do","ex":"Вопрос с глаголом play → Do."},{"t":"choice","q":"Do you live near here? — Yes, I ___.","o":["do","live","am"],"a":"do","ex":"Короткий ответ: Yes, I do."},{"t":"choice","q":"Do they work on Saturdays? — No, they ___.","o":["don't","aren't","not"],"a":"don't","ex":"Короткий ответ: No, they don't."},{"t":"choice","q":"We ___ a car.","o":["don't have","don't got","not have"],"a":"don't have","ex":"don't + have. «don't got» не бывает."},{"t":"choice","q":"___ you tired?","o":["Do","Are"],"a":"Are","ex":"tired — не действие. Вопрос с to be: Are you tired?"}]},{"title":"Сделайте отрицание (как в домашнем задании)","items":[{"t":"input","q":"I watch a lot of sport on TV.","a":["I don't watch a lot of sport on TV.","I do not watch a lot of sport on TV."],"ex":"watch → don't watch.","p":"Сделайте отрицание"},{"t":"input","q":"We have a lot of free time at the weekend.","a":["We don't have a lot of free time at the weekend.","We do not have a lot of free time at the weekend."],"ex":"have → don't have.","p":"Сделайте отрицание"},{"t":"input","q":"Our children like video games.","a":["Our children don't like video games.","Our children do not like video games."],"ex":"like → don't like.","p":"Сделайте отрицание"},{"t":"input","q":"They often make pasta for dinner.","a":["They don't often make pasta for dinner.","They do not often make pasta for dinner."],"ex":"don't + often + make.","p":"Сделайте отрицание"}]},{"title":"Задайте вопрос","items":[{"t":"input","q":"You play tennis.","a":["Do you play tennis?"],"ex":"Do + you + play tennis?","p":"Превратите в вопрос"},{"t":"input","q":"They live in London.","a":["Do they live in London?"],"ex":"Do + they + live in London?","p":"Превратите в вопрос"},{"t":"input","q":"You read the newspaper every day.","a":["Do you read the newspaper every day?"],"ex":"Do + you + read…?","p":"Превратите в вопрос"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"I not watch TV in the morning.","w":1,"c":"don't","ex":"Отрицание — don't."},{"t":"fix","q":"We don't got a car.","w":2,"c":"have","ex":"После don't — have."},{"t":"fix","q":"Are you like pizza?","w":0,"c":"Do","ex":"like — глагол-действие → Do you like…?"}]}]},{"id":"free","nav":"Свободное время","eyebrow":"Тема 3 · лексика","title":"Что вы делаете в свободное время","theory":"<p>Слова из урока «Free time». Учите их <b>сочетаниями</b>: глагол + слово. По-русски «ходить гулять», а по-английски <b>go for</b> a walk.</p>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>go</h4><ul><li>go online — выходить в интернет</li><li>go for a walk — гулять</li><li>go for a bike ride — кататься на велосипеде</li><li>go for a coffee — сходить выпить кофе</li><li>go to a concert — ходить на концерт</li><li>go shopping — ходить по магазинам</li></ul></div><div class=\"ng\"><h4>meet · see</h4><ul><li>meet friends — встречаться с друзьями</li><li>see friends — видеться с друзьями</li><li>visit a museum — сходить в музей</li></ul></div></div>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>play · watch · read</h4><ul><li>play sport / football — заниматься спортом / играть в футбол</li><li>watch TV / sport on TV — смотреть телевизор / спорт</li><li>read books / a newspaper — читать книги / газету</li></ul></div><div class=\"ng\"><h4>cook · paint · ride</h4><ul><li>cook dinner — готовить ужин</li><li>paint pictures — рисовать картины</li><li>ride a bike / a horse / a motorbike — ездить на велосипеде / лошади / мотоцикле</li></ul></div></div>\n<h3>like + -ing — любить что-то делать</h3>\n<p>После <b>like, love, hate</b> глагол обычно с <b>-ing</b>.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я люблю путешествовать.</span><span class=\"en\">I like <mark>travelling</mark>.</span><span class=\"why\">like + V-ing</span></li>\n<li><span class=\"ru\">Я люблю играть в видеоигры.</span><span class=\"en\">I like <mark>playing</mark> video games.</span></li>\n<li><span class=\"ru\">Мы ненавидим ходить по магазинам.</span><span class=\"en\">We hate <mark>going</mark> shopping.</span></li>\n</ul>\n<h3>Другие полезные фразы</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я ничего не делаю.</span><span class=\"en\">I do <mark>nothing</mark>.</span><span class=\"why\">nothing уже значит «ничего» — don't не нужен</span></li>\n<li><span class=\"ru\">Я занят работой.</span><span class=\"en\">I'm <mark>busy with</mark> my work.</span><span class=\"why\">to be busy with something</span></li>\n<li><span class=\"ru\">У меня застой, ничего не хочется.</span><span class=\"en\">I'm <mark>in a slump</mark>.</span><span class=\"why\">in a slump — в упадке, в застое</span></li>\n<li><span class=\"ru\">Понятно!</span><span class=\"en\">I <mark>get it</mark>!</span><span class=\"why\">get it — понять</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Встречаться с друзьями — без with: <span class=\"no\">I meet with friends.</span> <span class=\"yes\">I meet friends. ✔</span></span><span>Два отрицания подряд не ставят: <span class=\"no\">I don't do nothing.</span> <span class=\"yes\">I do nothing. ✔</span> <span class=\"yes\">I don't do anything. ✔</span></span><span>Гулять — go for a walk: <span class=\"no\">I go to walk.</span> <span class=\"yes\">I go for a walk. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>to ride a bike / a horse / a motorbike · go for a walk / a ride · to be busy with something · go to a concert · in a slump · I get it · like + V-ing: I like traveling · I do nothing</span></div>","groups":[{"title":"Выберите глагол","items":[{"t":"choice","q":"I ___ online every evening.","o":["go","play","do"],"a":"go","ex":"go online."},{"t":"choice","q":"We ___ friends on Saturdays.","o":["meet","watch","go"],"a":"meet","ex":"meet friends — без with."},{"t":"choice","q":"They ___ sport on TV.","o":["watch","see","play"],"a":"watch","ex":"watch sport on TV."},{"t":"choice","q":"My mum ___ pictures in her free time.","o":["paints","plays","does"],"a":"paints","ex":"paint pictures."},{"t":"choice","q":"Let's ___ for a coffee!","o":["go","do","have"],"a":"go","ex":"go for a coffee."},{"t":"choice","q":"I ___ a museum once a month.","o":["visit","go","meet"],"a":"visit","ex":"visit a museum. Можно и go to a museum."},{"t":"choice","q":"Do you ___ a bike?","o":["ride","drive","go"],"a":"ride","ex":"ride a bike."}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"I like ___ to music.","o":["listen","listening","to listen"],"a":"listening","ex":"like + V-ing: I like listening to music.","b":{"listen":"После like — listening."}},{"t":"choice","q":"«Я гуляю каждый день.»","o":["I go for a walk every day.","I go to walk every day.","I walk go every day."],"a":"I go for a walk every day.","ex":"go for a walk."},{"t":"choice","q":"«Я встречаюсь с друзьями.»","o":["I meet friends.","I meet with friends.","I am meet friends."],"a":"I meet friends.","ex":"meet friends — без with."},{"t":"choice","q":"«По выходным я ничего не делаю.»","o":["I do nothing at the weekend.","I don't do nothing at the weekend.","I am nothing at the weekend."],"a":"I do nothing at the weekend.","ex":"nothing уже отрицание."}]}]},{"id":"often","nav":"always · never","eyebrow":"Тема 4 · как часто","title":"always, usually, often, sometimes, never","theory":"<p>Эти слова говорят, <b>как часто</b> что-то происходит.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Значение</th><th>Как часто</th></tr></thead>\n<tbody>\n<tr><td><mark>always</mark></td><td>всегда</td><td>100%</td></tr>\n<tr><td><mark>usually</mark></td><td>обычно</td><td>≈ 90%</td></tr>\n<tr><td><mark>often</mark></td><td>часто</td><td>≈ 70%</td></tr>\n<tr><td><mark>sometimes</mark></td><td>иногда</td><td>≈ 50%</td></tr>\n<tr><td><mark>rarely</mark></td><td>редко</td><td>≈ 10%</td></tr>\n<tr><td><mark>hardly ever</mark></td><td>почти никогда</td><td>≈ 5%</td></tr>\n<tr><td><mark>never</mark></td><td>никогда</td><td>0%</td></tr>\n</tbody></table></div>\n<h3>Куда ставить</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Правило</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td><b>перед</b> глаголом-действием</td><td>I <mark>usually</mark> eat at home.</td></tr>\n<tr><td><b>после</b> am / is / are</td><td>I'm <mark>always</mark> busy.</td></tr>\n<tr><td><b>после</b> don't</td><td>We don't <mark>often</mark> eat pizza.</td></tr>\n<tr><td>sometimes можно и в начале</td><td><mark>Sometimes</mark> my mum cooks for us.</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я редко смотрю телевизор днём.</span><span class=\"en\">I <mark>rarely</mark> watch TV in the afternoon.</span></li>\n<li><span class=\"ru\">Я почти никогда не сижу в интернете вечером.</span><span class=\"en\">I <mark>hardly ever</mark> go online in the evenings.</span></li>\n<li><span class=\"ru\">Я никогда не пью кофе перед сном.</span><span class=\"en\">I <mark>never</mark> drink coffee before bed.</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>never, rarely, hardly ever уже отрицательные — don't не нужен: <span class=\"no\">I don't never go out.</span> <span class=\"yes\">I never go out. ✔</span></span><span>Слово частоты — перед глаголом, но после don't: <span class=\"no\">I usually don't enjoy films.</span> <span class=\"yes\">I don't usually enjoy films. ✔</span></span><span>Не разрывайте сочетание: <span class=\"no\">They go every day for a walk.</span> <span class=\"yes\">They go for a walk every day. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>I rarely meet with friends · I don't usually eat… · we rarely watch sport on TV · I hardly ever go online in the evenings</span></div>","groups":[{"title":"Выберите слово","items":[{"t":"choice","q":"I drink coffee every morning. I ___ drink coffee in the morning.","o":["always","sometimes","never"],"a":"always","ex":"Каждое утро → always."},{"t":"choice","q":"I don't like fish. I ___ eat it.","o":["often","usually","never"],"a":"never","ex":"Не люблю → никогда не ем: never."},{"t":"choice","q":"We go to the cinema two or three times a year. We ___ go to the cinema.","o":["always","rarely","usually"],"a":"rarely","ex":"Два-три раза в год — редко: rarely."},{"t":"choice","q":"She goes to the gym five days a week. She ___ goes to the gym.","o":["usually","hardly ever","never"],"a":"usually","ex":"Почти каждый день → usually."}]},{"title":"Где стоит слово? Выберите правильное предложение","items":[{"t":"choice","q":"(always)","o":["I'm always busy.","I always am busy.","Always I'm busy."],"a":"I'm always busy.","ex":"После am → I'm always busy."},{"t":"choice","q":"(usually)","o":["I usually get up at 7.","I get up usually at 7.","I get usually up at 7."],"a":"I usually get up at 7.","ex":"Перед глаголом-действием."},{"t":"choice","q":"(often)","o":["We don't often eat out.","We often don't eat out.","We don't eat often out."],"a":"We don't often eat out.","ex":"После don't: don't often."},{"t":"choice","q":"(never)","o":["I never go online in the morning.","I don't never go online in the morning.","I go never online in the morning."],"a":"I never go online in the morning.","ex":"never перед глаголом, без don't."}]},{"title":"Соберите предложение (как в домашнем задании)","items":[{"t":"order","w":["go","at","often","out","weekend","I","the"],"a":["I often go out at the weekend."],"ex":"I + often + go out + at the weekend."},{"t":"order","w":["rarely","watch","on","we","sport","TV"],"a":["We rarely watch sport on TV."],"ex":"We + rarely + watch + sport on TV."},{"t":"order","w":["dinner","sometimes","you","cook"],"a":["You sometimes cook dinner.","Sometimes you cook dinner."],"ex":"You + sometimes + cook + dinner."},{"t":"order","w":["every","they","for","go","a","day","walk"],"a":["They go for a walk every day."],"ex":"They + go for a walk + every day (в конце)."},{"t":"order","w":["in","ever","I","online","the","evenings","hardly","go"],"a":["I hardly ever go online in the evenings."],"ex":"I + hardly ever + go online + in the evenings."},{"t":"order","w":["drink","never","bed","coffee","before","I"],"a":["I never drink coffee before bed."],"ex":"I + never + drink coffee + before bed."}]},{"title":"Какое предложение правильное?","items":[{"t":"choice","q":"«Я никогда не ем мясо.»","o":["I never eat meat.","I don't never eat meat.","I never don't eat meat."],"a":"I never eat meat.","ex":"never уже значит «никогда», don't не нужен."},{"t":"choice","q":"«У тебя всегда пицца!»","o":["You always have pizza!","You have always pizza!","Always you have pizza!"],"a":"You always have pizza!","ex":"Слово частоты — перед глаголом have."},{"t":"choice","q":"«После работы я обычно устаю.»","o":["I'm usually tired after work.","I usually am tired after work.","I'm tired usually after work."],"a":"I'm usually tired after work.","ex":"После am: I'm usually tired."}]}]},{"id":"time","nav":"at · on · in","eyebrow":"Тема 5 · время","title":"Когда? at, on, in, every, once a week","theory":"<h3>at, on, in — предлоги времени</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Предлог</th><th>Когда</th><th>Примеры</th></tr></thead>\n<tbody>\n<tr><td><mark>at</mark></td><td>точное время, выходные, ночь</td><td>at 5 a.m. · at six o'clock · at night · at the weekend</td></tr>\n<tr><td><mark>on</mark></td><td>день недели, дата</td><td>on Monday · on Friday mornings · on 12 May</td></tr>\n<tr><td><mark>in</mark></td><td>месяц, год, время года, часть дня</td><td>in June · in 2020 · in summer · in the morning · in the evening</td></tr>\n</tbody></table></div>\n<p>Запомнить помогает пирамида: чем меньше отрезок времени, тем «острее» предлог. <b>in</b> — большие отрезки, <b>on</b> — день, <b>at</b> — точка.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Но: in the morning / in the evening, а ночью — <span class=\"yes\">at night ✔</span></span><span>Перед every, next, last предлог не ставят: <span class=\"no\">on every Monday</span> <span class=\"yes\">every Monday ✔</span></span></div>\n<h3>Как часто: every, once, twice</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Выражение</th><th>Значение</th></tr></thead>\n<tbody>\n<tr><td>every day / week / month / year</td><td>каждый день / неделю / месяц / год</td></tr>\n<tr><td>every morning / night</td><td>каждое утро / каждую ночь</td></tr>\n<tr><td><mark>once</mark> a week</td><td>раз в неделю</td></tr>\n<tr><td><mark>twice</mark> a month</td><td>два раза в месяц</td></tr>\n<tr><td><mark>three times</mark> a week</td><td>три раза в неделю</td></tr>\n</tbody></table></div>\n<p>Эти выражения обычно ставят <b>в конец</b> предложения: I go to the gym <b>three times a week</b>.</p>\n<h3>a.m. и p.m.</h3>\n<p><b>a.m.</b> — с полуночи до полудня (00–12), <b>p.m.</b> — с полудня до полуночи (12–00). 7 a.m. — 7 утра, 7 p.m. — 7 вечера.</p>\n<h3>Дни недели и месяцы — всегда с большой буквы</h3>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Days</h4><ul><li>Monday — понедельник</li><li>Tuesday — вторник</li><li>Wednesday — среда</li><li>Thursday — четверг</li><li>Friday — пятница</li><li>Saturday — суббота</li><li>Sunday — воскресенье</li></ul></div><div class=\"ng\"><h4>Months</h4><ul><li>January · February · March</li><li>April · May · June</li><li>July · August · September</li><li>October · November · December</li></ul></div></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>С большой буквы: <span class=\"no\">on monday, in april</span> <span class=\"yes\">on Monday, in April ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>at night / every night / every day · on + day · in + year / month / season · at 5 am · 3 times a week · am (00–12) / pm (12–00) · January … December · I run every morning</span></div>","groups":[{"title":"at, on или in?","items":[{"t":"choice","q":"I get up ___ 7 o'clock.","o":["at","on","in"],"a":"at","ex":"Точное время → at."},{"t":"choice","q":"We go to the gym ___ Tuesdays and Thursdays.","o":["at","on","in"],"a":"on","ex":"Дни недели → on."},{"t":"choice","q":"My birthday is ___ June.","o":["at","on","in"],"a":"in","ex":"Месяц → in."},{"t":"choice","q":"I don't work ___ the weekend.","o":["at","on","in"],"a":"at","ex":"at the weekend (брит.)."},{"t":"choice","q":"I read ___ the evening.","o":["at","on","in"],"a":"in","ex":"in the evening."},{"t":"choice","q":"I never drink coffee ___ night.","o":["at","on","in"],"a":"at","ex":"at night — исключение."},{"t":"choice","q":"They go to the sea ___ summer.","o":["at","on","in"],"a":"in","ex":"Время года → in."},{"t":"choice","q":"We have pizza ___ Friday evenings.","o":["at","on","in"],"a":"on","ex":"День недели + часть дня → on Friday evenings."}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"«Я хожу в спортзал три раза в неделю.»","o":["I go to the gym three times a week.","I go to the gym three times in week.","I three times go to the gym a week."],"a":"I go to the gym three times a week.","ex":"three times a week — в конце."},{"t":"choice","q":"«Мы встречаемся раз в месяц.»","o":["We meet once a month.","We meet one time in month.","We once meet a month."],"a":"We meet once a month.","ex":"раз в месяц = once a month."},{"t":"choice","q":"«Я бегаю каждое утро.»","o":["I run every morning.","I run in every morning.","I run every mornings."],"a":"I run every morning.","ex":"Перед every предлог не нужен, morning — без -s."},{"t":"choice","q":"3 p.m. — это ___","o":["3 часа дня","3 часа ночи"],"a":"3 часа дня","ex":"p.m. — после полудня."}]},{"title":"Напишите по-английски","items":[{"t":"input","q":"понедельник →","a":["Monday"],"ex":"Monday — с большой буквы.","p":"Напишите день недели","h":"Начинается на M."},{"t":"input","q":"среда →","a":["Wednesday"],"ex":"Wednesday — в середине «d», читается «венздей».","p":"Напишите день недели","h":"Wed…"},{"t":"input","q":"август →","a":["August"],"ex":"August — с большой буквы.","p":"Напишите месяц","h":"Начинается на A."},{"t":"input","q":"февраль →","a":["February"],"ex":"February — не забудьте r после b.","p":"Напишите месяц","h":"Feb…"}]}]},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"I ___ from home on Fridays.","o":["work","am work","working"],"a":"work","ex":"Тема 1: одно сказуемое — work."},{"t":"input","q":"We go out on Saturdays.","a":["We don't go out on Saturdays.","We do not go out on Saturdays."],"ex":"Тема 2: go → don't go.","p":"Сделайте отрицание"},{"t":"choice","q":"Do you like jazz? — No, I ___.","o":["don't","not","am not"],"a":"don't","ex":"Тема 2: No, I don't."},{"t":"choice","q":"I often ___ for a bike ride.","o":["go","do","play"],"a":"go","ex":"Тема 3: go for a bike ride."},{"t":"order","w":["have","usually","I","at","home","breakfast"],"a":["I usually have breakfast at home."],"ex":"Тема 4: usually — перед глаголом."},{"t":"choice","q":"«Я никогда не хожу в театр.»","o":["I never go to the theatre.","I don't never go to the theatre."],"a":"I never go to the theatre.","ex":"Тема 4: never без don't."},{"t":"choice","q":"My English classes are ___ Mondays.","o":["at","on","in"],"a":"on","ex":"Тема 5: дни недели → on."},{"t":"choice","q":"I like ___ books.","o":["read","reading","reads"],"a":"reading","ex":"Тема 3: like + V-ing."},{"t":"input","q":"they / live / in Spain?","a":["Do they live in Spain?"],"ex":"Тема 2: Do + they + live…?","p":"Составьте вопрос"},{"t":"choice","q":"I meet my grandma ___ Saturday.","o":["every","in every","on every"],"a":"every","ex":"Тема 5: перед every предлог не нужен."},{"t":"choice","q":"We visit my parents ___ a month.","o":["once","one","one time in"],"a":"once","ex":"Тема 5: once a month."},{"t":"order","w":["TV","I","the","in","watch","don't","usually","evening"],"a":["I don't usually watch TV in the evening."],"ex":"Тема 4: don't + usually + watch."}]}]}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 5: Present Simple: he, she, it (6 sections, 86 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('present-simple-he-she-it', 'Present Simple: he, she, it', 'окончание -s / -es, doesn''t и does, распорядок дня, профессии, числа', 5, $lesson${"sections":[{"id":"plus","nav":"she works","eyebrow":"Тема 1 · утверждение","title":"He works, she watches — окончание -s","theory":"<p>С <b>he, she, it</b> (и с любым одним человеком или предметом: Anna, my brother, the shop) к глаголу добавляется <b>-s</b>. Это единственное, что меняется.</p>\n<div class=\"formula\"><span class=\"slot\">he · she · it</span><span class=\"plus\">+</span><span class=\"slot be\">глагол + s / es</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span></div>\n<div class=\"compare\"><div><span class=\"en\">I work at night.</span><span class=\"ru\">Я работаю ночью.</span><span class=\"small\">I / you / we / they → work</span></div><div><span class=\"en\">Liam works at night.</span><span class=\"ru\">Лиам работает ночью.</span><span class=\"small\">he / she / it → works</span></div></div>\n<h3>Как добавлять -s</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Глагол кончается на…</th><th>Что делаем</th><th>Примеры</th></tr></thead>\n<tbody>\n<tr><td>почти все глаголы</td><td>+ <mark>s</mark></td><td>work → works · play → plays · get → gets</td></tr>\n<tr><td>-ch, -sh, -s, -x, -z, -o</td><td>+ <mark>es</mark></td><td>watch → watches · finish → finishes · go → goes · do → does</td></tr>\n<tr><td>согласная + y</td><td>y → <mark>ies</mark></td><td>study → studies · carry → carries · worry → worries</td></tr>\n<tr><td>гласная + y</td><td>просто + s</td><td>play → plays · say → says</td></tr>\n<tr><td>have</td><td>особая форма</td><td>have → <mark>has</mark></td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Кира встаёт в 2 часа ночи.</span><span class=\"en\">Keira <mark>gets</mark> up at 2 a.m.</span></li>\n<li><span class=\"ru\">Мой брат смотрит телевизор по вечерам.</span><span class=\"en\">My brother <mark>watches</mark> TV in the evening.</span><span class=\"why\">ch → es</span></li>\n<li><span class=\"ru\">Он заканчивает работу в 7 утра.</span><span class=\"en\">He <mark>finishes</mark> work at 7 a.m.</span><span class=\"why\">sh → es</span></li>\n<li><span class=\"ru\">Она учит экономику.</span><span class=\"en\">She <mark>studies</mark> economics.</span><span class=\"why\">y → ies</span></li>\n<li><span class=\"ru\">Джон принимает душ каждый вечер.</span><span class=\"en\">John <mark>has</mark> a shower every evening.</span><span class=\"why\">have → has</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Не забывайте -s: <span class=\"no\">She like pizza.</span> <span class=\"yes\">She likes pizza. ✔</span></span><span>-s только у глагола, не у всех слов подряд: <span class=\"no\">She likes pizzas very muchs.</span> <span class=\"yes\">She likes pizza very much. ✔</span></span><span>have → has, а не haves: <span class=\"no\">He haves lunch at 1.</span> <span class=\"yes\">He has lunch at 1. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>Present Simple · He / she / it · V + s / es · She likes food · play — He plays · have — he has · ch, sh, s, o, z, x + es: teaches · study — studies</span></div>","groups":[{"title":"Выберите правильную форму","items":[{"t":"choice","q":"My sister ___ in a hospital.","o":["work","works"],"a":"works","ex":"sister = she → works."},{"t":"choice","q":"They ___ in a big house.","o":["live","lives"],"a":"live","ex":"they → без -s."},{"t":"choice","q":"Liam ___ his job.","o":["love","loves"],"a":"loves","ex":"Liam = he → loves."},{"t":"choice","q":"The film ___ at 8 p.m.","o":["start","starts"],"a":"starts","ex":"film = it → starts."},{"t":"choice","q":"My parents ___ TV every evening.","o":["watch","watches"],"a":"watch","ex":"parents = they → watch."},{"t":"choice","q":"Tom ___ lunch at work.","o":["have","has","haves"],"a":"has","ex":"he → has."}]},{"title":"Напишите форму для he / she / it","items":[{"t":"input","q":"watch →","a":["watches"],"ex":"ch → + es.","p":"Напишите глагол с окончанием","h":"Кончается на ch."},{"t":"input","q":"go →","a":["goes"],"ex":"o → + es.","p":"Напишите глагол с окончанием","h":"Кончается на o."},{"t":"input","q":"study →","a":["studies"],"ex":"согласная + y → ies.","p":"Напишите глагол с окончанием","h":"y меняется."},{"t":"input","q":"play →","a":["plays"],"ex":"гласная + y → просто s.","p":"Напишите глагол с окончанием","h":"a перед y — гласная."},{"t":"input","q":"finish →","a":["finishes"],"ex":"sh → + es.","p":"Напишите глагол с окончанием","h":"Кончается на sh."},{"t":"input","q":"carry →","a":["carries"],"ex":"согласная + y → ies.","p":"Напишите глагол с окончанием","h":"r перед y — согласная."},{"t":"input","q":"do →","a":["does"],"ex":"o → + es.","p":"Напишите глагол с окончанием","h":"Кончается на o."},{"t":"input","q":"have →","a":["has"],"ex":"Особая форма.","p":"Напишите глагол с окончанием","h":"Не haves."}]},{"title":"Нажмите на неправильное слово (как в домашнем задании)","items":[{"t":"fix","q":"Sara watch TV every evening.","w":1,"c":"watches","ex":"Sara = she → watches."},{"t":"fix","q":"He carrys a big bag with him at work.","w":1,"c":"carries","ex":"согласная + y → carries."},{"t":"fix","q":"Sheena love her job.","w":1,"c":"loves","ex":"Sheena = she → loves."},{"t":"fix","q":"My dad gos to work by bus.","w":2,"c":"goes","ex":"go → goes."}]}]},{"id":"neg","nav":"doesn't · does","eyebrow":"Тема 2 · отрицание и вопрос","title":"She doesn't work. Does she work?","theory":"<p>В отрицании и вопросе с he / she / it появляется <b>does</b>. Окончание -s <b>переходит на does</b>, а глагол возвращается в словарную форму.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th></th><th>I / you / we / they</th><th>he / she / it</th></tr></thead>\n<tbody>\n<tr><td>+</td><td>I work.</td><td>She work<mark>s</mark>.</td></tr>\n<tr><td>−</td><td>I <mark>don't</mark> work.</td><td>She <mark>doesn't</mark> work.</td></tr>\n<tr><td>?</td><td><mark>Do</mark> you work?</td><td><mark>Does</mark> she work?</td></tr>\n<tr><td>Да</td><td>Yes, I do.</td><td>Yes, she does.</td></tr>\n<tr><td>Нет</td><td>No, I don't.</td><td>No, she doesn't.</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Лиам не обедает.</span><span class=\"en\">Liam <mark>doesn't have</mark> lunch.</span><span class=\"why\">не doesn't has</span></li>\n<li><span class=\"ru\">Ей не нравится её работа.</span><span class=\"en\">She <mark>doesn't like</mark> her job.</span><span class=\"why\">не doesn't likes</span></li>\n<li><span class=\"ru\">Он ходит в спортзал?</span><span class=\"en\"><mark>Does</mark> he <mark>go</mark> to the gym?</span><span class=\"why\">не Does he goes</span></li>\n</ul>\n<p>Правило простое: <b>-s</b> в предложении ставится <b>один раз</b>. Если уже есть does / doesn't, у глагола -s нет.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">She doesn't likes people.</span> <span class=\"yes\">She doesn't like people. ✔</span></span><span><span class=\"no\">Does she likes food?</span> <span class=\"yes\">Does she like food? ✔</span></span><span>С he / she / it — doesn't, а не don't: <span class=\"no\">Paulo don't have breakfast.</span> <span class=\"yes\">Paulo doesn't have breakfast. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>(−?) does · She doesn't like food · Does she like food? · yes, he does / no, he doesn't · I work / I don't work / he doesn't work / Does he work?</span></div>","groups":[{"title":"Выберите правильную форму","items":[{"t":"choice","q":"My brother ___ coffee.","o":["don't drink","doesn't drink","doesn't drinks"],"a":"doesn't drink","ex":"he → doesn't + drink (без -s).","b":{"don't drink":"brother = he → doesn't.","doesn't drinks":"-s уже ушла в doesn't, у drink её нет."}},{"t":"choice","q":"___ your sister live in London?","o":["Do","Does","Is"],"a":"Does","ex":"sister = she → Does."},{"t":"choice","q":"Does he work at night? — Yes, he ___.","o":["does","do","works"],"a":"does","ex":"Yes, he does."},{"t":"choice","q":"Does Anna like cats? — No, she ___.","o":["don't","doesn't","isn't"],"a":"doesn't","ex":"No, she doesn't."},{"t":"choice","q":"Chiara ___ to the gym.","o":["doesn't go","doesn't goes","don't go"],"a":"doesn't go","ex":"doesn't + go."},{"t":"choice","q":"Does he ___ a car?","o":["have","has","haves"],"a":"have","ex":"После Does — have."}]},{"title":"Сделайте отрицание","items":[{"t":"input","q":"She gets up early in the morning.","a":["She doesn't get up early in the morning.","She does not get up early in the morning."],"ex":"gets → doesn't get.","p":"Сделайте отрицание"},{"t":"input","q":"He plays video games.","a":["He doesn't play video games.","He does not play video games."],"ex":"plays → doesn't play.","p":"Сделайте отрицание"},{"t":"input","q":"My mum has breakfast at work.","a":["My mum doesn't have breakfast at work.","My mum does not have breakfast at work."],"ex":"has → doesn't have.","p":"Сделайте отрицание"}]},{"title":"Задайте вопрос","items":[{"t":"input","q":"She works in a hospital.","a":["Does she work in a hospital?"],"ex":"Does + she + work…?","p":"Превратите в вопрос"},{"t":"input","q":"He watches TV in the evening.","a":["Does he watch TV in the evening?"],"ex":"Does + he + watch…?","p":"Превратите в вопрос"},{"t":"input","q":"Your dad goes to bed early.","a":["Does your dad go to bed early?"],"ex":"Does + your dad + go…?","p":"Превратите в вопрос"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"She doesn't likes people.","w":2,"c":"like","ex":"После doesn't — like, без -s."},{"t":"fix","q":"Paulo don't have breakfast in the morning.","w":1,"c":"doesn't","ex":"Paulo = he → doesn't."},{"t":"fix","q":"Does she goes to work by bus?","w":2,"c":"go","ex":"После Does — go."}]}]},{"id":"day","nav":"Распорядок дня","eyebrow":"Тема 3 · лексика","title":"Мой день: get up, have a shower, go to bed","theory":"<p>Слова из урока «A night's work». Это устойчивые сочетания, их учат целиком.</p>\n<div class=\"ng-grid\"><div class=\"ng\"><h4>Утро</h4><ul><li>wake up — просыпаться</li><li>get up — вставать</li><li>have a shower / a bath — принимать душ / ванну</li><li>do my hair — делать причёску</li><li>get dressed — одеваться</li><li>get ready — собираться</li><li>have breakfast — завтракать</li><li>leave home — выходить из дома</li></ul></div><div class=\"ng\"><h4>День и вечер</h4><ul><li>go to work / school — идти на работу / в школу</li><li>start work — начинать работу</li><li>have lunch / dinner — обедать / ужинать</li><li>finish work — заканчивать работу</li><li>go to the gym — ходить в спортзал</li><li>do exercise — делать зарядку, тренироваться</li><li>get home — добираться домой</li><li>go to bed — ложиться спать</li></ul></div></div>\n<h3>home без to</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Фраза</th><th>Значение</th></tr></thead>\n<tbody>\n<tr><td>go <mark>home</mark></td><td>идти домой</td></tr>\n<tr><td>come <mark>home</mark></td><td>приходить домой</td></tr>\n<tr><td>get <mark>home</mark></td><td>добраться домой</td></tr>\n</tbody></table></div>\n<p>Со словом <b>home</b> предлог <b>to</b> не ставят. Но: go <b>to</b> work, go <b>to</b> bed.</p>\n<h3>get — одно слово, много значений</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я встаю в 7.</span><span class=\"en\">I <mark>get up</mark> at 7.</span><span class=\"why\">get up — вставать</span></li>\n<li><span class=\"ru\">Я добираюсь до работы в 9.</span><span class=\"en\">I <mark>get to</mark> work at 9.</span><span class=\"why\">get to — добираться</span></li>\n<li><span class=\"ru\">Я получил сообщение.</span><span class=\"en\">I <mark>get</mark> a message.</span><span class=\"why\">get — получать</span></li>\n<li><span class=\"ru\">Понятно.</span><span class=\"en\">I <mark>get it</mark>.</span><span class=\"why\">get it — понять</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Не «делаю завтрак», а «имею»: <span class=\"no\">I do breakfast.</span> <span class=\"no\">I eat a shower.</span> <span class=\"yes\">I have breakfast. ✔</span> <span class=\"yes\">I have a shower. ✔</span></span><span><span class=\"no\">I go to home.</span> <span class=\"yes\">I go home. ✔</span></span><span>wake up — проснуться, get up — встать с кровати. Это разные вещи.</span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>wake up · go home / come home / get home · get a message / get home / get to work / get it · like reading / want to go</span></div>","groups":[{"title":"Выберите глагол (как в домашнем задании)","items":[{"t":"choice","q":"I ___ a shower every morning.","o":["have","do","make"],"a":"have","ex":"have a shower."},{"t":"choice","q":"Hayley ___ dressed in five minutes.","o":["gets","does","makes"],"a":"gets","ex":"get dressed."},{"t":"choice","q":"I ___ my hair before work.","o":["do","have","make"],"a":"do","ex":"do my hair."},{"t":"choice","q":"She ___ home at 8.30 in the morning.","o":["leaves","goes","starts"],"a":"leaves","ex":"leave home — выходить из дома."},{"t":"choice","q":"We ___ exercise at the weekend.","o":["do","make","go"],"a":"do","ex":"do exercise."},{"t":"choice","q":"John ___ dinner with his family at 9 p.m.","o":["has","does","makes"],"a":"has","ex":"have dinner → has dinner."},{"t":"choice","q":"I ___ to bed early in the week.","o":["go","get","leave"],"a":"go","ex":"go to bed."},{"t":"choice","q":"What time do you ___ home?","o":["get","go to","leave to"],"a":"get","ex":"get home — без to."}]},{"title":"Какое предложение правильное?","items":[{"t":"choice","q":"«После работы я иду домой.»","o":["I go home after work.","I go to home after work.","I go at home after work."],"a":"I go home after work.","ex":"home без to: go home."},{"t":"choice","q":"«Вечером я принимаю душ.»","o":["I have a shower in the evening.","I do a shower in the evening.","I take shower in the evening."],"a":"I have a shower in the evening.","ex":"have a shower (можно take a shower, но с a)."},{"t":"choice","q":"«Она завтракает в 7.»","o":["She has breakfast at 7.","She does breakfast at 7.","She eats a breakfast at 7."],"a":"She has breakfast at 7.","ex":"have breakfast → has breakfast, без a."}]},{"title":"Соберите предложение","items":[{"t":"order","w":["at","a.m","gets","2","up","Keira"],"a":["Keira gets up at 2 a.m."],"ex":"Keira + gets up + at 2 a.m."},{"t":"order","w":["at","a","breakfast","work","has","she","quick"],"a":["She has a quick breakfast at work."],"ex":"She + has + a quick breakfast + at work."},{"t":"order","w":["goes","bed","straight","to","Liam"],"a":["Liam goes straight to bed."],"ex":"Liam + goes + straight to bed."}]}]},{"id":"jobs","nav":"Профессии","eyebrow":"Тема 4 · лексика","title":"What does she do? — She's a nurse.","theory":"<div class=\"ng-grid\"><div class=\"ng\"><h4>Профессии из урока</h4><ul><li>doctor — врач</li><li>nurse — медсестра, медбрат</li><li>police officer — полицейский</li><li>journalist — журналист</li><li>photographer — фотограф</li><li>musician — музыкант</li></ul></div><div class=\"ng\"><h4>И ещё</h4><ul><li>actor — актёр</li><li>farmer — фермер</li><li>cleaner — уборщик</li><li>driver — водитель</li><li>shop assistant — продавец</li><li>tennis player — теннисист</li><li>security guard — охранник</li></ul></div></div>\n<h3>Как спросить и ответить</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Кем она работает?</span><span class=\"en\"><mark>What does</mark> she <mark>do</mark>?</span><span class=\"why\">дословно: что она делает?</span></li>\n<li><span class=\"ru\">Она медсестра.</span><span class=\"en\">She's <mark>a</mark> nurse.</span><span class=\"why\">перед профессией — a</span></li>\n<li><span class=\"ru\">Он работает диджеем.</span><span class=\"en\">He <mark>works as a</mark> DJ.</span><span class=\"why\">work as + a + профессия</span></li>\n<li><span class=\"ru\">Я инженер.</span><span class=\"en\">I'm <mark>an</mark> engineer.</span><span class=\"why\">перед гласным звуком — an</span></li>\n</ul>\n<h3>-er, -or, -ist: как образуются профессии</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Действие</th><th>+ окончание</th><th>Профессия</th></tr></thead>\n<tbody>\n<tr><td>drive — водить</td><td>+ er</td><td>driv<mark>er</mark></td></tr>\n<tr><td>clean — убирать</td><td>+ er</td><td>clean<mark>er</mark></td></tr>\n<tr><td>farm — ферма</td><td>+ er</td><td>farm<mark>er</mark></td></tr>\n<tr><td>act — играть роль</td><td>+ or</td><td>act<mark>or</mark></td></tr>\n<tr><td>journal — журнал</td><td>+ ist</td><td>journal<mark>ist</mark></td></tr>\n</tbody></table></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Перед профессией нужен a / an: <span class=\"no\">She is doctor.</span> <span class=\"yes\">She is a doctor. ✔</span></span><span>police — <span class=\"no\">polica officer</span> <span class=\"yes\">police officer ✔</span></span><span>What does she do? — это про работу. Ответ не «She does…», а <span class=\"yes\">She's a nurse. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>actor · farmer · tennis player · cleaner · doctor · shop assistant · musician · journalist · photographer · driver · nurse · police officer · to work as a DJ / to work as a doctor</span></div>","groups":[{"title":"Кто это?","items":[{"t":"choice","q":"He plays music in concerts. He's a ___.","o":["musician","journalist","farmer"],"a":"musician","ex":"Играет музыку → musician."},{"t":"choice","q":"She sells things in a shop. She's a ___.","o":["shop assistant","cleaner","nurse"],"a":"shop assistant","ex":"Работает в магазине → shop assistant."},{"t":"choice","q":"He takes photos. He's a ___.","o":["photographer","driver","actor"],"a":"photographer","ex":"photo → photographer."},{"t":"choice","q":"She works in a hospital and helps doctors. She's a ___.","o":["nurse","police officer","farmer"],"a":"nurse","ex":"Помогает врачам → nurse."},{"t":"choice","q":"He writes for a newspaper. He's a ___.","o":["journalist","musician","cleaner"],"a":"journalist","ex":"Пишет в газету → journalist."},{"t":"choice","q":"She works in films and theatre. She's an ___.","o":["actor","driver","doctor"],"a":"actor","ex":"an actor — actor начинается с гласной."}]},{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"«Кем работает твой брат?»","o":["What does your brother do?","What is your brother do?","Who does your brother work?"],"a":"What does your brother do?","ex":"What does + he + do?"},{"t":"choice","q":"«Она врач.»","o":["She's a doctor.","She's doctor.","She does a doctor."],"a":"She's a doctor.","ex":"Перед профессией — a."},{"t":"choice","q":"«Он работает водителем.»","o":["He works as a driver.","He works a driver.","He is work as driver."],"a":"He works as a driver.","ex":"work as + a + профессия."}]},{"title":"Напишите профессию","items":[{"t":"input","q":"Он водит автобус. He's a ___.","a":["driver"],"ex":"drive + r → driver.","p":"Впишите одно слово","h":"drive + …"},{"t":"input","q":"Она работает на ферме. She's a ___.","a":["farmer"],"ex":"farm + er.","p":"Впишите одно слово","h":"farm + …"},{"t":"input","q":"Он убирает офисы. He's a ___.","a":["cleaner"],"ex":"clean + er.","p":"Впишите одно слово","h":"clean + …"}]}]},{"id":"numbers","nav":"Числа · текст","eyebrow":"Тема 5 · числа и чтение","title":"thirteen или thirty? И один день из жизни","theory":"<h3>-teen и -ty</h3>\n<p>Числа 13–19 кончаются на <b>-teen</b>, ударение в конце: thir<b>TEEN</b>. Десятки кончаются на <b>-ty</b>, ударение в начале: <b>THIR</b>ty.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>-teen</th><th>-ty</th></tr></thead>\n<tbody>\n<tr><td>13 thir<mark>teen</mark></td><td>30 thir<mark>ty</mark></td></tr>\n<tr><td>14 four<mark>teen</mark></td><td>40 for<mark>ty</mark> — без u!</td></tr>\n<tr><td>15 fif<mark>teen</mark></td><td>50 fif<mark>ty</mark></td></tr>\n<tr><td>20 — twen<mark>ty</mark></td><td>21 twenty-one — через дефис</td></tr>\n</tbody></table></div>\n<h3>Прочитайте текст</h3>\n<p><b>Ben</b> is a security guard. He works at night. He gets up at 7 p.m. and has a shower. Then he has dinner with his wife. He leaves home at 9.30 and gets to work at 10 p.m. He checks the building every hour. He doesn't have lunch, but he usually has a snack at 2 a.m. He finishes work at 6 a.m. and gets home at 7. His wife starts work at 8, so they have breakfast together. Then Ben goes straight to bed. He loves his job, but he doesn't see his friends very often.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>forty пишется без u: <span class=\"no\">fourty</span> <span class=\"yes\">forty ✔</span></span><span>Числа от 21 до 99 — через дефис: <span class=\"yes\">thirty-five ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>thirteen · twenty · thirty · forty · fifty · don't worry, be happy · She is here — host</span></div>","groups":[{"title":"Числа","items":[{"t":"choice","q":"40 — ___","o":["fourty","forty","fourteen"],"a":"forty","ex":"40 = forty, без u."},{"t":"choice","q":"13 — ___","o":["thirty","thirteen","threeteen"],"a":"thirteen","ex":"13 = thirteen."},{"t":"choice","q":"50 — ___","o":["fifty","fiveteen","fifteen"],"a":"fifty","ex":"50 = fifty."},{"t":"input","q":"35 →","a":["thirty-five","thirty five"],"ex":"thirty + five, через дефис.","p":"Напишите число словами","h":"thirty-…"},{"t":"input","q":"20 →","a":["twenty"],"ex":"20 = twenty.","p":"Напишите число словами","h":"Начинается на tw."}]},{"title":"По тексту про Бена: правда или нет?","items":[{"t":"choice","q":"Ben works at night.","o":["True","False"],"a":"True","ex":"He works at night."},{"t":"choice","q":"Ben has lunch at 2 a.m.","o":["True","False"],"a":"False","ex":"He doesn't have lunch, but he usually has a snack at 2 a.m."},{"t":"choice","q":"Ben and his wife have breakfast together.","o":["True","False"],"a":"True","ex":"His wife starts work at 8, so they have breakfast together."},{"t":"choice","q":"Ben sees his friends a lot.","o":["True","False"],"a":"False","ex":"He doesn't see his friends very often."},{"t":"choice","q":"What time does Ben get to work?","o":["At 9.30 p.m.","At 10 p.m.","At 7 p.m."],"a":"At 10 p.m.","ex":"He gets to work at 10 p.m."}]},{"title":"Впишите глагол в правильной форме (как в домашнем задании)","items":[{"t":"input","q":"Moyra ___ (get up) at 10 p.m.","a":["gets up"],"ex":"Moyra = she → gets up.","p":"Впишите глагол"},{"t":"input","q":"She ___ (not have) breakfast.","a":["doesn't have","does not have"],"ex":"she → doesn't have.","p":"Впишите глагол"},{"t":"input","q":"She ___ (finish) work at 7 a.m.","a":["finishes"],"ex":"sh → finishes.","p":"Впишите глагол"},{"t":"input","q":"Her children ___ (start) school at 8.","a":["start"],"ex":"children = they → start.","p":"Впишите глагол"},{"t":"input","q":"She ___ (say) «good night» to them.","a":["says"],"ex":"гласная + y → says.","p":"Впишите глагол"}]}]},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы урока вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"My dad ___ the newspaper every morning.","o":["read","reads","is read"],"a":"reads","ex":"Тема 1: dad = he → reads."},{"t":"input","q":"teach →","a":["teaches"],"ex":"Тема 1: ch → es.","p":"Напишите глагол для he / she / it","h":"Кончается на ch."},{"t":"choice","q":"She ___ meat.","o":["don't eat","doesn't eat","doesn't eats"],"a":"doesn't eat","ex":"Тема 2: doesn't + eat."},{"t":"fix","q":"Does he plays the piano?","w":2,"c":"play","ex":"Тема 2: после Does — play."},{"t":"choice","q":"Does your sister live with you? — No, she ___.","o":["doesn't","don't","isn't"],"a":"doesn't","ex":"Тема 2: No, she doesn't."},{"t":"choice","q":"I ___ home at 6 p.m.","o":["get","get to","go to"],"a":"get","ex":"Тема 3: get home — без to."},{"t":"choice","q":"He ___ a shower after the gym.","o":["has","does","makes"],"a":"has","ex":"Тема 3: have a shower → has."},{"t":"choice","q":"«Она учительница.»","o":["She's a teacher.","She's teacher.","She teaches a teacher."],"a":"She's a teacher.","ex":"Тема 4: a перед профессией."},{"t":"input","q":"your mum / what / do?","a":["What does your mum do?"],"ex":"Тема 4: What + does + your mum + do?","p":"Составьте вопрос о профессии"},{"t":"choice","q":"40 — ___","o":["forty","fourty"],"a":"forty","ex":"Тема 5: без u."},{"t":"order","w":["doesn't","the","at","weekend","work","she"],"a":["She doesn't work at the weekend."],"ex":"Тема 2: She + doesn't + work + at the weekend."},{"t":"fix","q":"Mark study economics at school.","w":1,"c":"studies","ex":"Тема 1: y → ies."}]}]}]}$lesson$::jsonb)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, position = excluded.position, content = excluded.content, updated_at = now();

-- Lesson 6: Вопросы: do, does и to be (6 sections, 81 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('questions-do-does', 'Вопросы: do, does и to be', 'Do you ever…?, Where do you…?, How often, to be или do, свободное время, much / many', 6, $lesson${"sections":[{"id":"yn","nav":"Do you…?","eyebrow":"Тема 1 · вопрос да / нет","title":"Do you ever go to the theatre?","theory":"<p>Вспомним: вопрос в Present Simple начинается с <b>Do</b> или <b>Does</b>. Глагол после них — всегда в словарной форме.</p>\n<div class=\"formula\"><span class=\"slot be\">Do · Does</span><span class=\"plus\">+</span><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Да</th><th>Нет</th></tr></thead>\n<tbody>\n<tr><td><mark>Do</mark> you play sport?</td><td>Yes, I do.</td><td>No, I don't.</td></tr>\n<tr><td><mark>Does</mark> she live here?</td><td>Yes, she does.</td><td>No, she doesn't.</td></tr>\n</tbody></table></div>\n<h3>ever — «вообще, когда-нибудь»</h3>\n<p><b>ever</b> в вопросе значит «хоть иногда, вообще». Ставится перед глаголом.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Ты вообще ходишь в театр?</span><span class=\"en\">Do you <mark>ever</mark> go to the theatre?</span><span class=\"why\">— Yes, I do. About once a year.</span></li>\n<li><span class=\"ru\">Ты когда-нибудь ходишь в кино один?</span><span class=\"en\">Do you <mark>ever</mark> go to the cinema on your own?</span></li>\n<li><span class=\"ru\">Она вообще занимается спортом?</span><span class=\"en\">Does she <mark>ever</mark> do sport?</span><span class=\"why\">— No, she doesn't.</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Без Do вопрос не получится: <span class=\"no\">You play the piano?</span> <span class=\"yes\">Do you play the piano? ✔</span></span><span>Do / Does — в начале, глагол — после «кто»: <span class=\"no\">Do play you video games?</span> <span class=\"yes\">Do you play video games? ✔</span></span><span>Не отвечайте глаголом: <span class=\"no\">Yes, I play.</span> <span class=\"yes\">Yes, I do. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>Do you ever go to the cinema on your own? · Do you play the piano? · Do you like…? · Yes, I do / No, I don't / yes, he does / no, he doesn't</span></div>","groups":[{"title":"Do или Does?","items":[{"t":"choice","q":"___ you get up early?","o":["Do","Does"],"a":"Do","ex":"you → Do."},{"t":"choice","q":"___ he know Jenny?","o":["Do","Does"],"a":"Does","ex":"he → Does."},{"t":"choice","q":"___ your parents live near you?","o":["Do","Does"],"a":"Do","ex":"parents = they → Do."},{"t":"choice","q":"___ she drink coffee?","o":["Do","Does"],"a":"Does","ex":"she → Does."},{"t":"choice","q":"___ Ron and Jan live here?","o":["Do","Does"],"a":"Do","ex":"Ron and Jan = they → Do."}]},{"title":"Выберите короткий ответ","items":[{"t":"choice","q":"Does he know Jenny? — Yes, he ___. They're good friends.","o":["does","knows","do"],"a":"does","ex":"Yes, he does."},{"t":"choice","q":"Does she drink coffee? — No, she ___. She drinks tea.","o":["doesn't","don't","isn't"],"a":"doesn't","ex":"No, she doesn't."},{"t":"choice","q":"Do they work at the hospital? — Yes, they ___.","o":["do","does","work"],"a":"do","ex":"Yes, they do."},{"t":"choice","q":"Do you ever go to concerts? — No, I ___.","o":["don't","doesn't","never"],"a":"don't","ex":"No, I don't."}]},{"title":"Соберите вопрос (как в учебнике)","items":[{"t":"order","w":["games","you","video","do","ever","play"],"a":["Do you ever play video games?"],"ex":"Do + you + ever + play + video games?"},{"t":"order","w":["do","piano","play","you","the"],"a":["Do you play the piano?"],"ex":"Do + you + play + the piano?"},{"t":"order","w":["ever","does","cook","your","brother","dinner"],"a":["Does your brother ever cook dinner?"],"ex":"Does + your brother + ever + cook + dinner?"}]}]},{"id":"wh","nav":"Where do you…?","eyebrow":"Тема 2 · вопрос со словами","title":"Where do you live? How often does she…?","theory":"<p>Вопросительное слово ставим <b>в самое начало</b>. Дальше порядок такой же, как в вопросе «да / нет».</p>\n<div class=\"formula\"><span class=\"slot\">вопр. слово</span><span class=\"plus\">+</span><span class=\"slot be\">do · does</span><span class=\"plus\">+</span><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span><span class=\"plus\">+</span><span class=\"slot\">?</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Перевод</th></tr></thead>\n<tbody>\n<tr><td><mark>Where do</mark> you live?</td><td>Где ты живёшь?</td></tr>\n<tr><td><mark>What time do</mark> you get up?</td><td>Во сколько ты встаёшь?</td></tr>\n<tr><td><mark>When does</mark> she watch TV?</td><td>Когда она смотрит телевизор?</td></tr>\n<tr><td><mark>How often do</mark> you go to the gym?</td><td>Как часто ты ходишь в спортзал?</td></tr>\n<tr><td><mark>What music do</mark> you listen to?</td><td>Какую музыку ты слушаешь?</td></tr>\n<tr><td><mark>How many times a year do</mark> you go to the cinema?</td><td>Сколько раз в год ты ходишь в кино?</td></tr>\n<tr><td><mark>What do</mark> you do at the weekend?</td><td>Что ты делаешь по выходным?</td></tr>\n<tr><td><mark>How does</mark> he travel to work?</td><td>Как он добирается до работы?</td></tr>\n</tbody></table></div>\n<h3>Предлог — в конце</h3>\n<p>Если глагол требует предлога (listen <b>to</b>, look <b>at</b>, talk <b>about</b>), в вопросе предлог уходит <b>в конец</b>.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Какую музыку ты слушаешь?</span><span class=\"en\">What music do you listen <mark>to</mark>?</span></li>\n<li><span class=\"ru\">О чём ты думаешь?</span><span class=\"en\">What are you thinking <mark>about</mark>?</span></li>\n</ul>\n<h3>Как составить вопрос к ответу</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я живу в Мадриде.</span><span class=\"en\">I live <u>in Madrid</u>. → <mark>Where do</mark> you live?</span></li>\n<li><span class=\"ru\">Он работает в Мельбурне.</span><span class=\"en\">He works <u>in Melbourne</u>. → <mark>Where does</mark> he work?</span></li>\n<li><span class=\"ru\">Я встаю в 6.</span><span class=\"en\">I get up <u>at six o'clock</u>. → <mark>What time do</mark> you get up?</span></li>\n<li><span class=\"ru\">Картина стоит 2000 фунтов.</span><span class=\"en\">The painting costs <u>£2000</u>. → <mark>How much does</mark> it cost?</span><span class=\"why\">или How much is it?</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Не пропускайте do / does: <span class=\"no\">Where you live?</span> <span class=\"yes\">Where do you live? ✔</span></span><span>После does глагол без -s: <span class=\"no\">Where does she lives?</span> <span class=\"yes\">Where does she live? ✔</span></span><span>«Во сколько» — What time, а не How late: <span class=\"no\">How late do you go to bed?</span> <span class=\"yes\">What time do you go to bed? ✔</span></span><span>Цена: <span class=\"no\">How much does it costs?</span> <span class=\"yes\">How much does it cost? ✔</span> <span class=\"yes\">How much is it? ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>where does she live? · Where do you listen to music? · How often do you watch TV? · How many times a year do you go to the cinema? · How much is this painting? / how much does it cost?</span></div>","groups":[{"title":"Выберите правильный вопрос","items":[{"t":"choice","q":"«Где работает твой папа?»","o":["Where does your dad work?","Where your dad works?","Where does your dad works?"],"a":"Where does your dad work?","ex":"Where + does + your dad + work?","b":{"Where your dad works?":"Пропущено does.","Where does your dad works?":"После does — work, без -s."}},{"t":"choice","q":"«Во сколько ты встаёшь?»","o":["What time do you get up?","How late do you get up?","What time you get up?"],"a":"What time do you get up?","ex":"Время → What time."},{"t":"choice","q":"«Какую музыку ты слушаешь?»","o":["What music do you listen to?","What music do you listen?","To what music you listen?"],"a":"What music do you listen to?","ex":"listen to — to в конце."},{"t":"choice","q":"«Сколько это стоит?»","o":["How much does it cost?","How much does it costs?","How many does it cost?"],"a":"How much does it cost?","ex":"How much + does + it + cost."}]},{"title":"Задайте вопрос — вопросительное слово в скобках (как в домашнем задании)","items":[{"t":"input","q":"She lives in Madrid. (Где?)","a":["Where does she live?"],"ex":"Where + does + she + live?","p":"Задайте вопрос"},{"t":"input","q":"I listen to music two or three times a week. (Как часто?)","a":["How often do you listen to music?"],"ex":"How often + do + you + listen to music?","p":"Задайте вопрос"},{"t":"input","q":"He works in Melbourne. (Где?)","a":["Where does he work?"],"ex":"Where + does + he + work?","p":"Задайте вопрос"},{"t":"input","q":"I get up at six o'clock. (Во сколько?)","a":["What time do you get up?","When do you get up?"],"ex":"What time + do + you + get up?","p":"Задайте вопрос"},{"t":"input","q":"She watches TV in the living room. (Где?)","a":["Where does she watch TV?"],"ex":"Where + does + she + watch TV?","p":"Задайте вопрос"},{"t":"input","q":"We go to bed at ten o'clock. (Во сколько?)","a":["What time do you go to bed?","When do you go to bed?"],"ex":"What time + do + you + go to bed?","p":"Задайте вопрос"},{"t":"input","q":"Heather only eats meat on Mondays. (Когда?)","a":["When does Heather eat meat?","When does she eat meat?"],"ex":"When + does + Heather + eat meat?","p":"Задайте вопрос"}]},{"title":"Соберите вопрос","items":[{"t":"order","w":["often","you","watch","TV","do","how"],"a":["How often do you watch TV?"],"ex":"How often + do + you + watch TV?"},{"t":"order","w":["does","study","where","Harry"],"a":["Where does Harry study?"],"ex":"Where + does + Harry + study?"},{"t":"order","w":["the","at","weekend","what","do","do","you"],"a":["What do you do at the weekend?"],"ex":"What + do + you + do + at the weekend?"},{"t":"order","w":["the","times","how","year","go","cinema","to","do","you","a","many"],"a":["How many times a year do you go to the cinema?"],"ex":"How many times a year + do + you + go to the cinema?"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"Where does she lives?","w":3,"c":"live","ex":"После does — live."},{"t":"fix","q":"What time you get up?","w":2,"c":"do you","ex":"Нужен do: What time do you get up?"},{"t":"fix","q":"How much does it costs?","w":4,"c":"cost","ex":"После does — cost."}]}]},{"id":"be-do","nav":"to be или do?","eyebrow":"Тема 3 · главное различие","title":"Is he at home? или Does he work?","theory":"<p>Самое важное в этом уроке. В английском два типа предложений, и вопросы в них строятся по-разному.</p>\n<div class=\"compare\"><div><span class=\"en\">am · is · are</span><span class=\"ru\">Глагола-действия нет. to be не переводится: «он (есть) дома».</span><span class=\"small\">He is at home. · He isn't at home. · Is he at home?</span></div><div><span class=\"en\">do · does</span><span class=\"ru\">Есть глагол-действие: работать, жить, любить.</span><span class=\"small\">He works. · He doesn't work. · Does he work?</span></div></div>\n<h3>Как выбрать</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>После «кто» идёт…</th><th>Нужно</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>какой? (прилагательное)</td><td><mark>am / is / are</mark></td><td>Are you tired? · She isn't happy.</td></tr>\n<tr><td>где? (место)</td><td><mark>am / is / are</mark></td><td>Where are you? — I'm at home.</td></tr>\n<tr><td>кто? (профессия, имя)</td><td><mark>am / is / are</mark></td><td>Is he a doctor?</td></tr>\n<tr><td>возраст</td><td><mark>am / is / are</mark></td><td>How old are you?</td></tr>\n<tr><td>интересуется</td><td><mark>am / is / are</mark></td><td>Are you interested in football?</td></tr>\n<tr><td>действие (глагол)</td><td><mark>do / does</mark></td><td>Do you like football? · Where does he work?</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Сколько ей лет?</span><span class=\"en\">How old <mark>is</mark> she?</span><span class=\"why\">возраст → is</span></li>\n<li><span class=\"ru\">Где он работает?</span><span class=\"en\">Where <mark>does</mark> he work?</span><span class=\"why\">work — действие → does</span></li>\n<li><span class=\"ru\">Кто твой любимый актёр?</span><span class=\"en\"><mark>Who is</mark> your favourite actor?</span><span class=\"why\">о человеке — Who</span></li>\n<li><span class=\"ru\">Какая твоя любимая еда?</span><span class=\"en\"><mark>What is</mark> your favourite food?</span></li>\n<li><span class=\"ru\">Как часто ты бываешь дома?</span><span class=\"en\">How often <mark>are</mark> you at home?</span><span class=\"why\">at home — место → are</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Не смешивайте: <span class=\"no\">Do you are tired?</span> <span class=\"no\">Are you like pizza?</span> <span class=\"yes\">Are you tired? ✔</span> <span class=\"yes\">Do you like pizza? ✔</span></span><span>«Я согласен» — это действие: <span class=\"no\">I am agree.</span> <span class=\"yes\">I agree. ✔</span></span><span>О человеке спрашиваем Who: <span class=\"no\">What is your favourite actor?</span> <span class=\"yes\">Who is your favourite actor? ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>to be — глагол без перевода, связка в предложении: I am at home / He is a doctor / Is he a good man? · I work / I don't work / Does he work? · to be (am is are) — нет переводящегося глагола</span></div>","groups":[{"title":"am / is / are или do / does? (как в домашнем задании)","items":[{"t":"choice","q":"I ___ in a café now.","o":["am","do"],"a":"am","ex":"в кафе — место → am."},{"t":"choice","q":"___ she play tennis every week?","o":["Is","Does"],"a":"Does","ex":"play — действие → Does."},{"t":"choice","q":"___ she a singer?","o":["Is","Does"],"a":"Is","ex":"singer — кто → Is."},{"t":"choice","q":"___ they on the bus?","o":["Are","Do"],"a":"Are","ex":"on the bus — место → Are."},{"t":"choice","q":"Why ___ he in France?","o":["is","does"],"a":"is","ex":"in France — место → is."},{"t":"choice","q":"It ___ cold today.","o":["isn't","doesn't"],"a":"isn't","ex":"cold — какой → isn't."},{"t":"choice","q":"They ___ like animals.","o":["aren't","don't"],"a":"don't","ex":"like — действие → don't."},{"t":"choice","q":"Where ___ you? — I'm at home.","o":["are","do"],"a":"are","ex":"где ты → are."},{"t":"choice","q":"What ___ the dog eat?","o":["is","does"],"a":"does","ex":"eat — действие → does."},{"t":"choice","q":"He ___ an accountant.","o":["isn't","doesn't"],"a":"isn't","ex":"accountant — профессия → isn't."},{"t":"choice","q":"___ you interested in football?","o":["Are","Do"],"a":"Are","ex":"interested — какой → Are."},{"t":"choice","q":"We ___ make too much noise at night.","o":["aren't","don't"],"a":"don't","ex":"make — действие → don't."}]},{"title":"Выберите правильный вопрос","items":[{"t":"choice","q":"«Кто твой любимый актёр?»","o":["Who is your favourite actor?","What is your favourite actor?","Who does your favourite actor?"],"a":"Who is your favourite actor?","ex":"О человеке — Who, актёр — «кто» → is."},{"t":"choice","q":"«Сколько тебе лет?»","o":["How old are you?","How old do you have?","How many years do you have?"],"a":"How old are you?","ex":"Возраст — через to be."},{"t":"choice","q":"«Ты согласен?»","o":["Do you agree?","Are you agree?","Do you are agree?"],"a":"Do you agree?","ex":"agree — глагол-действие → Do."}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"Are you like pizza?","w":0,"c":"Do","ex":"like — действие → Do you like…?"},{"t":"fix","q":"Do you tired today?","w":0,"c":"Are","ex":"tired — какой → Are you tired?"},{"t":"fix","q":"Where do your parents from?","w":1,"c":"are","ex":"from — откуда (to be): Where are your parents from?"},{"t":"fix","q":"Do your sister like football?","w":0,"c":"Does","ex":"sister = she → Does your sister like…?"}]}]},{"id":"free","nav":"play · listen · watch · go","eyebrow":"Тема 4 · лексика","title":"Свободное время: play, listen to, watch, go","theory":"<p>Слова из урока «Going out». Главное — какой глагол с каким словом.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Глагол</th><th>С чем</th><th>Перевод</th></tr></thead>\n<tbody>\n<tr><td><mark>play</mark></td><td>video games · games online · the piano · the guitar</td><td>играть в видеоигры · играть на пианино / гитаре</td></tr>\n<tr><td><mark>listen to</mark></td><td>music · the radio · a song</td><td>слушать музыку / радио / песню</td></tr>\n<tr><td><mark>watch</mark></td><td>TV · a TV programme · a film · a video online · a football match</td><td>смотреть телевизор / передачу / фильм / видео / матч</td></tr>\n<tr><td><mark>go to</mark></td><td>the cinema · a concert · the theatre</td><td>ходить в кино / на концерт / в театр</td></tr>\n<tr><td><mark>go</mark></td><td>out · dancing · shopping</td><td>выходить куда-то · ходить на танцы · по магазинам</td></tr>\n</tbody></table></div>\n<h3>На что обратить внимание</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я слушаю музыку в машине.</span><span class=\"en\">I <mark>listen to</mark> music in the car.</span><span class=\"why\">listen всегда с to</span></li>\n<li><span class=\"ru\">Он играет на гитаре.</span><span class=\"en\">He plays <mark>the</mark> guitar.</span><span class=\"why\">перед музыкальным инструментом — the</span></li>\n<li><span class=\"ru\">Я смотрю матч по телевизору.</span><span class=\"en\">I watch a football match <mark>on</mark> TV.</span><span class=\"why\">on TV — по телевизору</span></li>\n<li><span class=\"ru\">Давай сходим в музей.</span><span class=\"en\">Let's <mark>visit a museum</mark> / <mark>go to a museum</mark>.</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">I listen music.</span> <span class=\"yes\">I listen to music. ✔</span></span><span><span class=\"no\">I play piano.</span> <span class=\"yes\">I play the piano. ✔</span></span><span>Смотреть фильм — watch, а не see: <span class=\"no\">I see TV.</span> <span class=\"yes\">I watch TV. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>play video games / games online / the piano or guitar · listen to music / the radio / a song · watch TV / a film / a video online / a football match · go to the cinema / a concert / the theatre · visit a museum / go to a museum</span></div>","groups":[{"title":"Выберите глагол (как в домашнем задании)","items":[{"t":"choice","q":"How often do you ___ football on TV?","o":["watch","see","listen"],"a":"watch","ex":"watch football on TV."},{"t":"choice","q":"I always ___ music in the car.","o":["listen","listen to","watch"],"a":"listen to","ex":"listen to music."},{"t":"choice","q":"I try to ___ a museum once a month.","o":["visit","watch","play"],"a":"visit","ex":"visit a museum."},{"t":"choice","q":"She ___ games online.","o":["plays","watches","goes"],"a":"plays","ex":"play games online."},{"t":"choice","q":"Let's ___ the theatre tonight.","o":["go to","go","visit to"],"a":"go to","ex":"go to the theatre."},{"t":"choice","q":"Do you ever ___ videos online?","o":["watch","listen to","go"],"a":"watch","ex":"watch videos online."},{"t":"choice","q":"John and Gina ___ the cinema every weekend.","o":["go to","watch","play"],"a":"go to","ex":"go to the cinema."}]},{"title":"Какое слово лишнее?","items":[{"t":"choice","q":"play: video games / the guitar / ___ / games online","o":["the radio","the piano"],"a":"the radio","ex":"the radio — listen to, а не play."},{"t":"choice","q":"listen to: the radio / a song / ___","o":["music","TV"],"a":"music","ex":"TV — watch."},{"t":"choice","q":"watch: TV / a film / ___","o":["a football match","the piano"],"a":"a football match","ex":"the piano — play."},{"t":"choice","q":"go to: the cinema / a concert / ___","o":["the theatre","a song"],"a":"the theatre","ex":"a song — listen to."}]}]},{"id":"words","nav":"Фразы с доски","eyebrow":"Тема 5 · фразы со стикеров","title":"much, many и другие фразы с доски","theory":"<h3>much или many</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th></th><th>many</th><th>much</th></tr></thead>\n<tbody>\n<tr><td>С чем</td><td>то, что можно посчитать</td><td>то, что нельзя посчитать</td></tr>\n<tr><td>Примеры</td><td>many apples · many friends · many times</td><td>much sugar · much time · much money</td></tr>\n<tr><td>Вопрос</td><td><mark>How many</mark> apples?</td><td><mark>How much</mark> sugar? · How much is it?</td></tr>\n</tbody></table></div>\n<p>В утверждениях чаще говорят <b>a lot of</b> — подходит к обоим: a lot of apples, a lot of time.</p>\n<h3>Полезные фразы</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Мне это трудно.</span><span class=\"en\">I <mark>find it difficult</mark>.</span><span class=\"why\">find it + прилагательное</span></li>\n<li><span class=\"ru\">Не думаю, что ты прав.</span><span class=\"en\">I <mark>don't think</mark> you're right.</span><span class=\"why\">отрицание — в think</span></li>\n<li><span class=\"ru\">Не волнуйся, будь счастлив.</span><span class=\"en\"><mark>Don't worry</mark>, be happy.</span><span class=\"why\">просьба: Don't + глагол</span></li>\n<li><span class=\"ru\">например</span><span class=\"en\"><mark>e.g.</mark> = for example</span><span class=\"why\">e.g. go to a restaurant, the cinema…</span></li>\n<li><span class=\"ru\">и так далее</span><span class=\"en\"><mark>etc.</mark> = et cetera</span><span class=\"why\">books, films, music etc.</span></li>\n<li><span class=\"ru\">гулять с кем-то</span><span class=\"en\">to walk <mark>with</mark> somebody</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">How much apples?</span> <span class=\"yes\">How many apples? ✔</span></span><span>«Я не думаю, что…» — отрицание в think: <span class=\"no\">I think you aren't right.</span> <span class=\"yes\">I don't think you're right. ✔</span></span><span><span class=\"no\">I find difficult it.</span> <span class=\"yes\">I find it difficult. ✔</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>many apples / much sugar · I find it difficult · I don't think you are right · e.g. = for example · etc. = et cetera · don't worry, be happy · Don't you forget it?</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"How ___ brothers have you got?","o":["much","many"],"a":"many","ex":"brothers можно посчитать → many."},{"t":"choice","q":"How ___ is this painting?","o":["much","many"],"a":"much","ex":"Цена → How much."},{"t":"choice","q":"I don't drink ___ tea.","o":["much","many"],"a":"much","ex":"tea нельзя посчитать → much."},{"t":"choice","q":"She hasn't got ___ friends here.","o":["much","many"],"a":"many","ex":"friends → many."},{"t":"choice","q":"«Мне это трудно.»","o":["I find it difficult.","I find difficult it.","It finds me difficult."],"a":"I find it difficult.","ex":"find it + difficult."},{"t":"choice","q":"«Не думаю, что это правда.»","o":["I don't think it's true.","I think it isn't true.","I not think it's true."],"a":"I don't think it's true.","ex":"Отрицание — в think."},{"t":"choice","q":"«e.g.» значит ___","o":["for example","and so on","everything"],"a":"for example","ex":"e.g. = for example, например."}]}]},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · уроки 4–6","title":"Проверьте себя","theory":"<p>Задания по всему Present Simple и вопросам. Если ошибётесь, вернитесь к объяснению через меню сверху или откройте уроки 4 и 5.</p>","groups":[{"title":"Смешанные задания (как в домашнем задании)","items":[{"t":"input","q":"(he / drive to work every day)","a":["Does he drive to work every day?"],"ex":"Урок 6, тема 2: Does + he + drive…?","p":"Составьте вопрос"},{"t":"input","q":"(you / have enough time?)","a":["Do you have enough time?","Have you got enough time?"],"ex":"Тема 1: Do + you + have…?","p":"Составьте вопрос"},{"t":"input","q":"(I / eat cereal in the morning)","a":["I eat cereal in the morning."],"ex":"Урок 4: I + eat…","p":"Составьте утверждение"},{"t":"input","q":"(he / not / read the newspaper)","a":["He doesn't read the newspaper.","He does not read the newspaper."],"ex":"Урок 5: doesn't + read.","p":"Составьте отрицание"},{"t":"choice","q":"___ she dance often?","o":["Does","Is","Do"],"a":"Does","ex":"Тема 1: she + dance → Does."},{"t":"choice","q":"What ___ you do at the weekend?","o":["do","are","does"],"a":"do","ex":"Тема 2: What + do + you + do?"},{"t":"choice","q":"How ___ he travel to work?","o":["does","is","do"],"a":"does","ex":"Тема 2: How + does + he + travel?"},{"t":"input","q":"(they / not / like vegetables)","a":["They don't like vegetables.","They do not like vegetables."],"ex":"Урок 4: don't + like.","p":"Составьте отрицание"},{"t":"input","q":"(she / catch a cold every winter)","a":["She catches a cold every winter."],"ex":"Урок 5: catch → catches.","p":"Составьте утверждение"},{"t":"choice","q":"___ you at home now?","o":["Are","Do"],"a":"Are","ex":"Тема 3: at home — место → Are."},{"t":"fix","q":"Where does Harry studies?","w":3,"c":"study","ex":"Тема 2: после does — study."},{"t":"choice","q":"I ___ music on the radio.","o":["listen to","listen","watch"],"a":"listen to","ex":"Тема 4: listen to."},{"t":"order","w":["often","does","the","she","go","how","gym","to"],"a":["How often does she go to the gym?"],"ex":"Тема 2: How often + does + she + go…?"},{"t":"choice","q":"How ___ sugar do you want?","o":["many","much"],"a":"much","ex":"Тема 5: sugar → much."}]}]}]}$lesson$::jsonb)
